"""Reviewed function-only candidate fixture. No imports, configuration, or entrypoint.

Generated by scripts/prepare_execution_test_fixtures.py from exact pinned sources.
Drift against a locally available reviewed source is checked by the harness.
"""

def _max_notional(acct):
    return LIVE_MAX_NOTIONAL_BY_ACCT.get(str(acct or "").lower(), LIVE_MAX_NOTIONAL)

def _max_opt_risk(acct):
    return LIVE_MAX_OPT_RISK_BY_ACCT.get(str(acct or "").lower(), LIVE_MAX_OPT_RISK)

def _uncapped_futures(acct):
    return str(acct or "").lower() in UNCAPPED_FUTURES_ACCOUNTS

def _uncapped_options(acct):
    return str(acct or "").lower() in UNCAPPED_OPTIONS_ACCOUNTS

def _fx_usd_exposure(symbol, currency, qty, entry, stop):
    """Return (notional_usd, risk_usd) for a USD FX pair.

    IBKR CASH quantities are BASE-currency units and prices are QUOTE-currency
    units per base. Crosses with no USD leg need a separate conversion quote
    and are rejected by the entry gate.
    """
    base = str(symbol or "").upper()
    quote = str(currency or "").upper()
    if quote == "USD":
        return qty * entry, qty * abs(entry - stop)
    if base == "USD":
        return qty, qty * abs(entry - stop) / entry
    raise ValueError("CASH entry supports USD pairs only initially")

def _on_err(reqId, code, msg, *a):
    if code not in _BENIGN:
        _ERRORS.append(f"{code}:{msg}")

def _out(ok, state, detail, fill=None):
    print(json.dumps({"ok": ok, "state": state, "detail": detail, "fill": fill}))
    return 0

def _command_signal(p, role):
    """Durable identity for one broker mutation within a signed command."""
    command_id = str(p.get("_command_id") or "").strip()
    role = str(role or "").strip()
    if not command_id:
        raise ValueError("durable command id is required")
    if not role:
        raise ValueError("broker mutation role is required")
    return f"EXEC|{command_id}|{role}"

def _resolve_broker_account(ib, logical_account):
    """Resolve the exact IBKR account; never pick managedAccounts()[0]."""
    logical = str(logical_account or "").strip().upper()
    configured = os.environ.get(f"LEGEND_ETF_{logical}_ACCOUNT", "").strip()
    managed = sorted({
        str(value).strip()
        for value in ib.managedAccounts()
        if str(value).strip()
    })
    if configured:
        if configured not in managed:
            raise ValueError(
                f"configured {logical} broker account is not managed by this connection"
            )
        return configured
    if len(managed) != 1:
        raise ValueError(
            f"{logical or 'logical'} account is not configured and the connection "
            "does not prove exactly one managed account"
        )
    return managed[0]

def _payload_matches(c, sym, sec_type, expiry):
    """True when contract c matches the flatten payload's symbol [+ sec_type
    [+ expiry]]. A missing payload field matches anything (legacy tickets); the
    site sends expiry as YYYYMM (book_snapshot truncates), so compare on the
    prefix of IB's full YYYYMMDD lastTradeDateOrContractMonth."""
    if str(c.symbol).upper() != sym:
        return False
    if sec_type and str(c.secType).upper() != sec_type:
        return False
    if expiry:
        c_exp = str(getattr(c, "lastTradeDateOrContractMonth", "") or "")
        if not c_exp.startswith(expiry):
            return False
    return True

def _payload_contract_matches(c, p):
    """Match the exact confirmed contract, preferring IBKR conId."""
    try:
        want_cid = int(p.get("con_id") or 0)
        got_cid = int(getattr(c, "conId", 0) or 0)
    except (TypeError, ValueError):
        return False
    if want_cid and got_cid:
        return want_cid == got_cid
    currency = str(p.get("currency") or "").upper()
    if currency and str(getattr(c, "currency", "") or "").upper() != currency:
        return False
    return _payload_matches(
        c,
        str(p.get("symbol") or "").upper(),
        str(p.get("sec_type") or "").upper(),
        str(p.get("expiry") or "").strip(),
    )

def _exact_position(ib, p):
    account = str(p.get("_broker_account") or "").strip()
    try:
        con_id = int(p.get("con_id") or 0)
    except (TypeError, ValueError):
        con_id = 0
    if not account:
        return None, "exact broker account is unavailable"
    if con_id <= 0:
        return None, "positive con_id is required for an existing-position command"
    matches = [
        position
        for position in ib.positions()
        if str(getattr(position, "account", "") or "").strip() == account
        and float(getattr(position, "position", 0) or 0) != 0
        and int(getattr(position.contract, "conId", 0) or 0) == con_id
    ]
    if not matches:
        return None, f"no exact {account}/{con_id} position in {p.get('symbol', '?')}"
    if len(matches) > 1:
        return None, (f"{len(matches)} positions match {p.get('symbol', '?')}; "
                      "con_id/expiry is not exact enough")
    position = matches[0]
    if not _payload_contract_matches(position.contract, p):
        return None, "account/conId position does not match the confirmed payload contract"
    return position, None

def _fast_qty(held, p, *, partial):
    raw = p.get("qty")
    if raw not in (None, ""):
        try:
            q = float(raw)
        except (TypeError, ValueError):
            return None, "qty must be a number"
        if q <= 0 or q != int(q):
            return None, "qty must be a whole number > 0"
        n = int(q)
    else:
        default = 0.5 if partial else 1.0
        try:
            frac = float(p.get("fraction", default) or default)
        except (TypeError, ValueError):
            return None, "fraction must be a number"
        if frac <= 0 or (partial and frac >= 1.0):
            return None, f"fraction must be {'in (0, 1)' if partial else '> 0'}"
        n = int(math.floor(held * frac + 0.5))
    if n <= 0:
        return None, "resolved quantity is zero"
    if partial and n >= held:
        return None, f"trim quantity {n} must be below held {held}"
    return n, None

def _contract_matches(c, ref):
    """True when a working order's contract c is the SAME instrument as ref (the
    matched position's contract): conId when both sides carry one, else
    symbol + secType + expiry (YYYYMM prefix). Never matches on bare symbol --
    two contract months of one futures root are different instruments."""
    cid_c, cid_r = int(getattr(c, "conId", 0) or 0), int(getattr(ref, "conId", 0) or 0)
    if cid_c and cid_r:
        return cid_c == cid_r
    if str(c.symbol).upper() != str(ref.symbol).upper():
        return False
    if str(c.secType).upper() != str(ref.secType).upper():
        return False
    exp_c = str(getattr(c, "lastTradeDateOrContractMonth", "") or "")
    exp_r = str(getattr(ref, "lastTradeDateOrContractMonth", "") or "")
    return exp_c[:6] == exp_r[:6]

def _orders_for_contract(ib, ref, account):
    con_id = int(getattr(ref, "conId", 0) or 0)
    account = str(account or "").strip()
    if con_id <= 0 or not account:
        raise ValueError("working-order lookup requires exact account and positive conId")
    blank_account_is_exact = _blank_account_is_exact(ib, account)
    matches = []
    for trade in _fresh_open_trades(ib):
        if int(getattr(trade.contract, "conId", 0) or 0) != con_id:
            continue
        if str(getattr(trade.orderStatus, "status", "") or "") in TERMINAL:
            continue
        trade_account = str(getattr(trade.order, "account", "") or "").strip()
        if not trade_account:
            if not blank_account_is_exact:
                raise ValueError(
                    "working order on the exact contract has an ambiguous blank account"
                )
        elif trade_account != account:
            continue
        matches.append(trade)
    return matches

def _cancel_via_owners(ib, host, port, main_cid, targets):
    import execution_lifecycle
    return execution_lifecycle.cancel_many(globals(), ib, host, port, main_cid, targets)

def _confirm_cancelled(ib, targets, tries=4):
    """Poll until none of the targeted orders (by permId) is still working, or
    give up. Returns the list of orders STILL working (empty == all cancelled).
    permId-scoped so an order deliberately left alone (another contract month,
    or a pending entry during a trim) can't block confirmation."""
    want = set(int(t.order.permId) for t in targets)
    working = []
    for _ in range(tries):
        ib.sleep(1.5)
        ib.reqAllOpenOrders()
        ib.sleep(0.4)
        working = [t for t in ib.openTrades()
                   if int(t.order.permId) in want and t.orderStatus.status not in TERMINAL]
        if not working:
            return []
    return working

def _px(v):
    """A real, placeable price or 0.0 (ib_insync uses UNSET_DOUBLE ~1.8e308)."""
    try:
        v = float(v)
    except (TypeError, ValueError):
        return 0.0
    return v if 0 < v < 1e12 else 0.0

def _order_source_key(o):
    """Durable per-leg identity: the broker's permId when it has assigned one,
    else the placing client's own orderId. None when neither is readable."""
    perm_id = int(getattr(o, "permId", 0) or 0)
    order_id = int(getattr(o, "orderId", 0) or 0)
    client_id = int(getattr(o, "clientId", 0) or 0)
    if perm_id > 0:
        return f"perm:{perm_id}"
    if order_id > 0:
        return f"client:{client_id}:order:{order_id}"
    return None

def _split_pending_entry_legs(targets):
    """Split working orders into (protective, pending_entry_children).

    A closing leg whose PARENT order is STILL WORKING belongs to an unfilled
    entry bracket: it protects nothing yet, its quantity describes the pending
    entry rather than the live position, and resizing it against the held size
    would corrupt an order the user never asked to touch. Same convention as
    olv_book_cap's book discovery ("a bracket whose BUY parent is still working
    is an unfilled ENTRY, otherwise a filled LEG").

    `targets` comes from _orders_for_contract, which already drops terminal
    orders and covers BOTH directions -- so a still-working parent is present
    in the same list and its orderId is enough to classify its children.
    """
    working_ids = {int(getattr(t.order, "orderId", 0) or 0) for t in targets
                   if int(getattr(t.order, "orderId", 0) or 0) > 0}
    protective, pending = [], []
    for t in targets:
        parent_id = int(getattr(t.order, "parentId", 0) or 0)
        if parent_id > 0 and parent_id in working_ids:
            pending.append(t)
        else:
            protective.append(t)
    return protective, pending

def _capture_exit_legs(targets, close_action):
    """Describe the working exit legs (close-direction orders) so a partial trim
    can re-place them at the reduced quantity. Returns (legs, err): err set when
    any leg can't be represented faithfully -- the caller must then abort BEFORE
    cancelling anything (fail safe). Same-direction pending entries are skipped
    (a trim leaves them alone)."""
    legs = []
    for i, t in enumerate(targets):
        o = t.order
        if str(o.action).upper() != close_action:
            continue
        typ = str(o.orderType).upper()
        try:
            qty = float(o.totalQuantity or 0)
        except (TypeError, ValueError):
            qty = 0
        if qty <= 0 or qty != int(qty):
            return None, f"exit leg permId {o.permId} has invalid quantity {qty!r}"
        source_tif = str(getattr(o, "tif", "") or "").strip().upper()
        if not source_tif:
            return None, f"exit leg permId {o.permId} has blank TIF"
        source_key = _order_source_key(o)
        if source_key is None:
            return None, "exit leg has no durable broker identity"
        leg = {"order_type": typ, "tif": source_tif,
               "oca_group": o.ocaGroup or "", "oca_type": int(o.ocaType or 1),
               "good_after": o.goodAfterTime or "", "good_till": o.goodTillDate or "",
               "outside_rth": bool(o.outsideRth),
               "lmt": _px(o.lmtPrice), "aux": _px(o.auxPrice),
               "qty": int(qty), "order_ref": (getattr(o, "orderRef", "") or ""),
               "source_key": source_key}
        if typ == "STP":
            if not leg["aux"]:
                return None, f"stop leg permId {o.permId} has no readable stop price"
        elif typ == "LMT":
            if not leg["lmt"]:
                return None, f"limit leg permId {o.permId} has no readable limit price"
        elif typ == "MKT":
            if not leg["good_after"]:
                return None, f"market exit leg permId {o.permId} has no schedule"
        else:
            return None, f"exit leg permId {o.permId} has unsupported type {typ}"
        legs.append(leg)
    return legs, None

def _leg_group_key(leg, i):
    return leg.get("oca_group") or f"solo:{leg.get('source_key', i)}"

def _validate_exit_topology(legs, held_qty, require_protective_exit=True):
    """Validate one or more OCA rungs and exact closing-exit coverage.

    Exposure-adding fast actions require either a readable price stop or a
    scheduled MKT time stop.  A plain partial close can resize any supported
    closing exits because it reduces rather than adds exposure.
    """
    if not legs:
        return "no working closing bracket"
    if require_protective_exit and not any(
            (leg["order_type"] == "STP" and leg["aux"] > 0)
            or (leg["order_type"] == "MKT" and leg["good_after"])
            for leg in legs):
        return "no working price stop or scheduled time stop"
    groups = {}
    for i, leg in enumerate(legs):
        groups.setdefault(_leg_group_key(leg, i), []).append(int(leg["qty"]))
    coverage = 0
    for key, quantities in groups.items():
        if len(set(quantities)) != 1:
            return f"OCA group {key} has inconsistent leg quantities {quantities}"
        coverage += quantities[0]
    if coverage != int(held_qty):
        return f"closing bracket covers {coverage}, expected {int(held_qty)}"
    return None

def _scaled_exit_legs(legs, new_total):
    """Clone legs with per-rung quantities scaled by largest-remainder rounding."""
    groups, order = {}, []
    for i, leg in enumerate(legs):
        key = _leg_group_key(leg, i)
        if key not in groups:
            groups[key] = {"qty": int(leg["qty"]), "legs": []}
            order.append(key)
        groups[key]["legs"].append(leg)
    if not groups:
        return None, "no bracket to scale"
    new_total = int(new_total)
    if new_total < len(groups):
        return None, f"quantity {new_total} is too small to preserve {len(groups)} bracket rungs"
    original = sum(groups[k]["qty"] for k in order)
    raw = {k: new_total * groups[k]["qty"] / original for k in order}
    alloc = {k: max(1, int(math.floor(raw[k]))) for k in order}
    while sum(alloc.values()) > new_total:
        candidates = [k for k in order if alloc[k] > 1]
        if not candidates:
            return None, "bracket rung rounding is not representable"
        k = min(candidates, key=lambda x: (raw[x] - math.floor(raw[x]), order.index(x)))
        alloc[k] -= 1
    fractions = {k: raw[k] - math.floor(raw[k]) for k in order}
    while sum(alloc.values()) < new_total:
        k = max(order, key=lambda x: (fractions[x], -order.index(x)))
        alloc[k] += 1
        fractions[k] = -1.0
    out = []
    for k in order:
        for leg in groups[k]["legs"]:
            clone = dict(leg)
            clone["scaled_qty"] = alloc[k]
            out.append(clone)
    return out, None

def _place_exit_legs(ib, contract, legs, close_action, qty, account,
                     operation_id, parent_id=0, transmit_chain=False):
    """Place a proportionally scaled clone of captured exit legs."""
    scaled, err = _scaled_exit_legs(legs, qty)
    if err:
        raise ValueError(err)
    oca_names = {}
    placed = []
    for leg in scaled:
        typ = leg["order_type"]
        leg_qty = leg["scaled_qty"]
        if typ == "STP":
            o = StopOrder(close_action, leg_qty, leg["aux"])
        elif typ == "LMT":
            o = LimitOrder(close_action, leg_qty, leg["lmt"])
        else:
            o = MarketOrder(close_action, leg_qty)
        o.orderId = ib.client.getReqId()
        o.tif = leg["tif"]
        if parent_id:
            o.parentId = parent_id
            o.transmit = False
        if leg["oca_group"]:
            old = leg["oca_group"]
            if old not in oca_names:
                oca_names[old] = f"OCA_{o.orderId}"
            o.ocaGroup = oca_names[old]
            o.ocaType = leg["oca_type"]
        if leg["good_after"]:
            o.goodAfterTime = leg["good_after"]
        if leg["good_till"]:
            o.goodTillDate = leg["good_till"]
        if leg["outside_rth"]:
            o.outsideRth = True
        if leg.get("order_ref"):
            o.orderRef = leg["order_ref"]
        if account:
            o.account = account           # route to the account holding the position
        placed.append(
            guarded_place_order(
                ib,
                contract,
                o,
                mutation_kind="protective" if parent_id else "exit",
                signal_id=f"{operation_id}|leg:{leg['source_key']}|place",
            )
        )
    if transmit_chain and placed:
        # Re-place the last child with transmit=True to release its parent and all
        # sibling children as one attached bracket.
        last = placed[-1]
        release_order = copy.deepcopy(last.order)
        release_order.transmit = True
        placed[-1] = guarded_place_order(
            ib,
            contract,
            release_order,
            mutation_kind="modify" if parent_id else "exit",
            signal_id=f"{operation_id}|leg:{scaled[-1]['source_key']}|release",
        )
    ib.sleep(1.5)
    return placed, scaled

def _replace_exit_legs(ib, contract, legs, close_action, qty, account, operation_id):
    placed, _ = _place_exit_legs(
        ib, contract, legs, close_action, qty, account, operation_id
    )
    return placed

def _placed_ids(trades):
    return [{"order_id": int(getattr(t.order, "orderId", 0) or 0),
             "perm_id": int(getattr(t.order, "permId", 0) or 0),
             "status": getattr(t.orderStatus, "status", "")}
            for t in trades]

def _placement_problem(trades, ib=None):
    if ib is not None:
        for _ in range(24):
            if all(t.orderStatus.status in {"Submitted", "PreSubmitted", "Filled"} for t in trades):
                break
            if any(t.orderStatus.status in TERMINAL - {"Filled"} for t in trades):
                break
            ib.sleep(0.25)
    if _ERRORS:
        return "; ".join(_ERRORS[-4:])
    accepted = {"PRESUBMITTED", "SUBMITTED", "FILLED"}
    statuses = [
        str(getattr(trade.orderStatus, "status", "") or "").strip().upper()
        for trade in trades
    ]
    bad = [status for status in statuses if status not in accepted]
    if bad:
        return (
            f"{len(bad)} order(s) lack positive broker-live/fill proof "
            f"({', '.join(status or '<blank>' for status in bad)})"
        )
    return None

def build_order_ref(symbol, action, strategy, ref_date=None):
    """-> (ref, error). A pipe would corrupt parse_ref's field split, so the
    character class is closed rather than merely escaped. SPACES ARE LEGAL:
    the scan pipeline's own tags are names like 'Oversold Low Volume', and a
    dashboard order must be able to carry the same tag as its strategy."""
    strat = str(strategy or "").strip()
    if not strat:
        return None, "strategy tag is empty"
    if len(strat) > STRATEGY_REF_MAX:
        return None, f"strategy tag longer than {STRATEGY_REF_MAX} chars"
    if not re.fullmatch(r"[A-Za-z0-9 _.-]+", strat):
        return None, "strategy tag allows only letters, digits, spaces, _ . and - (no pipes)"
    d = str(ref_date or "").strip() or datetime.date.today().isoformat()
    try:
        datetime.date.fromisoformat(d)
    except ValueError:
        return None, "ref_date must be a date (YYYY-MM-DD)"
    return f"{str(symbol).upper().strip()}|{str(action).upper().strip()}|{strat}|{d}", None

def build_bracket(action, qty, entry, stop, target, account, next_id, time_stop_gat=None,
                  parent_gtd=None, stop_outside_rth=False, entry_type="LMT", entry_cap=None,
                  order_ref=None, stop_gat=None):
    """stop=None builds a stop-less chain (UNPROTECTED unless target/time legs
    remain); with no children at all the parent transmits itself. MKT/MOO/MOC use
    ``entry`` only as the caller's risk reference; it is not placed on the order.
    STP_LMT places ``entry`` as the STOP TRIGGER and ``entry_cap`` as the limit,
    so the fill lands anywhere in [entry, entry_cap] (BUY) -- callers must size
    and gate off the CAP, which is the worst acceptable fill.
    ``order_ref`` stamps every leg (parent + children) with the book-wide
    orderRef tag `SYMBOL|ACTION|Strategy_Ref|Date`, which is how the execution
    report, the Trade Log tab and any maintenance job identify whose order this
    is. Untagged legs read as Discretionary."""
    exit_a = "SELL" if action == "BUY" else "BUY"
    entry_type = str(entry_type or "LMT").upper()
    if entry_type == "LMT":
        parent = LimitOrder(action, qty, entry)
    elif entry_type == "STP_LMT":
        if entry_cap is None:
            raise ValueError("STP_LMT requires entry_cap")
        parent = StopLimitOrder(action, qty, entry_cap, entry)   # lmtPrice=cap, auxPrice=trigger
    elif entry_type == "MKT":
        parent = MarketOrder(action, qty)
    elif entry_type == "MOO":
        parent = MarketOrder(action, qty)
    elif entry_type == "MOC":
        parent = MarketOrder(action, qty)
        parent.orderType = "MOC"
    else:
        raise ValueError(f"unsupported entry_type {entry_type}")
    parent.orderId = next_id(); parent.transmit = False
    if parent_gtd and entry_type in ("LMT", "STP_LMT"):  # entry expiry: priced-parent GTD
        parent.tif = "GTD"; parent.goodTillDate = parent_gtd
    elif entry_type == "MOO":
        parent.tif = "OPG"
    else:
        parent.tif = "DAY"
    if account:
        parent.account = account
    oca = f"OCA_{parent.orderId}"
    children = []
    if target is not None:
        tgt = LimitOrder(exit_a, qty, target)
        tgt.orderId = next_id(); tgt.parentId = parent.orderId
        tgt.ocaGroup = oca; tgt.ocaType = 1; tgt.tif = "GTC"; tgt.transmit = False
        if account:
            tgt.account = account
        children.append(tgt)
    if stop is not None:
        stp = StopOrder(exit_a, qty, stop)
        stp.orderId = next_id(); stp.parentId = parent.orderId
        stp.ocaGroup = oca; stp.ocaType = 1; stp.tif = "GTC"; stp.transmit = False
        if stop_gat:
            stp.goodAfterTime = stop_gat  # stop_arm=next_session: day-2 arming
        if stop_outside_rth:
            stp.outsideRth = True       # futures: the protective stop must survive the overnight session
        if account:
            stp.account = account
        children.append(stp)
    if time_stop_gat:
        # TIME exit: a MKT held inactive until goodAfterTime, then closes at market.
        # Mirrors the TIME child in eq_order_entry.py (OCA, outsideRth=True).
        tm = MarketOrder(exit_a, qty)
        tm.orderId = next_id(); tm.parentId = parent.orderId
        tm.ocaGroup = oca; tm.ocaType = 1; tm.tif = "GTC"
        tm.goodAfterTime = time_stop_gat; tm.outsideRth = True; tm.transmit = False
        if account:
            tm.account = account
        children.append(tm)
    if children:
        children[-1].transmit = True   # the LAST leg transmits the whole bracket
    else:
        parent.transmit = True         # naked entry: nothing else to release it
    if order_ref:
        # EVERY leg carries the tag, not just the parent: a maintenance job that
        # reprices a stop finds the leg by ref, and the exits must be
        # attributable after the parent is gone.
        for o in (parent, *children):
            o.orderRef = order_ref
    return parent, children

def snap_combo_limit(limit, action, tick=OPT_COMBO_TICK):
    """Snap a combo net limit to the order tick grid, never worsening the price:
    a BUY (debit) rounds DOWN, a SELL (credit) rounds UP. Combos often display on
    a 0.01 grid but only accept orders on 0.05 -- the snap must go toward-safe."""
    import math
    limit, tick = float(limit), float(tick)
    if tick <= 0:
        return round(limit, 4)
    n = limit / tick
    snapped = (math.floor(n + 1e-9) if str(action).upper() == "BUY"
               else math.ceil(n - 1e-9)) * tick
    return round(snapped, 4)

def opt_spread_risk(debit_risk, qty, legs):
    """Per-order dollar risk basis: debit-at-risk x 100 x spreads + round-trip
    commissions on every leg contract."""
    n_contracts = qty * sum(int(l.get("ratio", 1) or 1) for l in legs)
    comm = OPT_COMM_PER_CONTRACT * n_contracts * 2
    return float(debit_risk) * 100.0 * qty + comm

def option_combo_risk(action, limit, qty, legs):
    """Return (defined-risk dollars incl. round-trip commissions, error).

    The mapped executor intentionally supports only one long standard option
    or a canonical 1:1 same-series vertical.  This excludes ratio spreads,
    calendars, mixed rights, and multi-wing structures whose tail risk cannot
    be represented by one directional reservation.
    """
    action = str(action).upper()
    try:
        limit, qty = float(limit), int(qty)
    except (TypeError, ValueError):
        return None, "quantity/limit must be numbers"
    if action not in ("BUY", "SELL"):
        return None, "action must be BUY or SELL"
    if qty <= 0 or limit <= 0:
        return None, "quantity and limit must be > 0"
    if len(legs) not in {1, 2}:
        return None, "only one long option or one 1:1 vertical is supported"
    if any(int(l.get("ratio", 1) or 1) != 1 for l in legs):
        return None, "option ratios are not supported"
    n_contracts = qty * len(legs)
    comm = OPT_COMM_PER_CONTRACT * n_contracts * 2
    if len(legs) == 1:
        leg = legs[0]
        if action != "BUY" or str(leg.get("side") or "").upper() != "BUY":
            return None, "a single option must be a 1:1 BUY"
        return limit * 100.0 * qty + comm, None
    if len({str(leg.get("expiry") or "") for leg in legs}) != 1:
        return None, "vertical legs must share one expiry"
    if len({str(leg.get("right") or "").upper() for leg in legs}) != 1:
        return None, "vertical legs must share one option right"
    if {str(leg.get("side") or "").upper() for leg in legs} != {"BUY", "SELL"}:
        return None, "vertical needs one BUY leg and one SELL leg"
    bought = next(leg for leg in legs if str(leg["side"]).upper() == "BUY")
    sold = next(leg for leg in legs if str(leg["side"]).upper() == "SELL")
    right = str(bought["right"]).upper()
    canonical = (
        float(bought["strike"]) < float(sold["strike"])
        if right == "C"
        else float(bought["strike"]) > float(sold["strike"])
    )
    if not canonical:
        return None, "vertical legs are not in canonical debit orientation"
    width = abs(float(bought["strike"]) - float(sold["strike"]))
    if width <= 0 or limit >= width:
        return None, f"net price {limit:g} must be below vertical width {width:g}"
    unit_loss = limit if action == "BUY" else width - limit
    return unit_loss * 100.0 * qty + comm, None

def _trusted_option_topology(action, limit, qty, legs, qualified_contracts):
    """Validate broker-qualified contracts and derive risk/direction.

    Payload direction is deliberately absent from this interface.
    """
    risk, error = option_combo_risk(action, limit, qty, legs)
    if error:
        return None, error
    if len(qualified_contracts) != len(legs):
        return None, "qualified option count does not match the order legs"
    con_ids = []
    series = set()
    for index, (leg, contract) in enumerate(zip(legs, qualified_contracts), start=1):
        try:
            con_id = int(getattr(contract, "conId", 0) or 0)
            multiplier = float(getattr(contract, "multiplier", 0) or 0)
            strike = float(getattr(contract, "strike", 0) or 0)
        except (TypeError, ValueError):
            return None, f"qualified leg {index} has invalid contract fields"
        sec_type = str(getattr(contract, "secType", "") or "").upper()
        currency = str(getattr(contract, "currency", "") or "").upper()
        symbol = str(getattr(contract, "symbol", "") or "").upper()
        trading_class = str(getattr(contract, "tradingClass", "") or "").upper()
        expiry = str(getattr(contract, "lastTradeDateOrContractMonth", "") or "")[:8]
        right = str(getattr(contract, "right", "") or "").upper()
        if con_id <= 0 or con_id in con_ids:
            return None, "qualified option conIds must be positive and unique"
        if sec_type != "OPT" or currency != "USD" or multiplier != 100:
            return None, "qualified option must be a standard USD 100-multiplier contract"
        if not symbol or not trading_class:
            return None, "qualified option lacks symbol/tradingClass identity"
        if (
            expiry != leg["expiry"] or right != leg["right"]
            or abs(strike - float(leg["strike"])) > 1e-9
        ):
            return None, f"qualified leg {index} does not match its requested series"
        con_ids.append(con_id)
        series.add((symbol, trading_class))
    if len(series) != 1:
        return None, "option legs cross symbol or tradingClass"

    if len(legs) == 1:
        direction = "long" if legs[0]["right"] == "C" else "short"
    else:
        base = "long" if legs[0]["right"] == "C" else "short"
        direction = base if str(action).upper() == "BUY" else (
            "short" if base == "long" else "long"
        )
    return {"risk_usd": risk, "portfolio_direction": direction}, None

def build_combo(symbol, qualified_legs):
    """BAG contract from qualified legs [(con_id, ratio, side), ...]. Leg actions
    are as-given (the ticket describes the BUY orientation; a SELL parent order
    inverts them at IBKR). SMART-routed like the stock path."""
    combo = Contract(symbol=symbol, secType="BAG", currency="USD", exchange="SMART")
    combo.comboLegs = [
        ComboLeg(conId=int(cid), ratio=int(ratio), action=str(side).upper(), exchange="SMART")
        for cid, ratio, side in qualified_legs
    ]
    return combo

def _parse_spread_legs(p):
    """(legs, err) -- normalized leg dicts from the payload, or an error string."""
    legs = p.get("legs")
    if not isinstance(legs, list) or not (1 <= len(legs) <= 2):
        return None, "option_spread needs one long option or one 2-leg vertical"
    out = []
    for i, l in enumerate(legs):
        side = str(l.get("side", "")).upper()
        right = str(l.get("right", "")).upper()
        expiry = str(l.get("expiry", "")).replace("-", "").strip()
        try:
            strike = float(l.get("strike"))
            ratio = int(l.get("ratio", 1) or 1)
            con_id = int(l.get("con_id") or 0)
        except (TypeError, ValueError):
            return None, f"leg {i + 1}: strike/ratio/con_id must be numbers"
        if side not in ("BUY", "SELL"):
            return None, f"leg {i + 1}: side must be BUY/SELL"
        if right not in ("C", "P"):
            return None, f"leg {i + 1}: right must be C/P"
        if len(expiry) != 8 or not expiry.isdigit():
            return None, f"leg {i + 1}: expiry must be YYYYMMDD"
        if not math.isfinite(strike) or strike <= 0:
            return None, f"leg {i + 1}: strike must be > 0"
        if ratio < 1 or float(l.get("ratio", 1) or 1) != ratio:
            return None, f"leg {i + 1}: ratio must be >= 1"
        out.append({"side": side, "right": right, "expiry": expiry,
                    "strike": strike, "ratio": ratio, "con_id": con_id})
    return out, None

def _do_option_spread(ib, p, acct):
    if p.get("dynamic_selection"):
        return _do_dynamic_option_limit(ib, p, acct)
    broker_account = str(p.get("_broker_account") or "").strip()
    if not broker_account:
        return _out(False, "rejected", "live gate: exact broker account is unavailable")
    sym = str(p.get("symbol", "")).upper()
    action = str(p.get("action", "")).upper()
    tif = str(p.get("tif") or "DAY").upper()
    try:
        qty = float(p.get("quantity"))
        limit = float(p.get("limit"))
        claimed_risk = float(p.get("debit_risk"))
    except (TypeError, ValueError):
        return _out(False, "rejected", "live gate: quantity/limit/debit_risk must be numbers")
    if not sym:
        return _out(False, "rejected", "live gate: symbol required")
    if str(acct or "").lower() not in OPTION_ACCOUNTS:
        return _out(False, "rejected", f"live gate: options execution is disabled for {acct}")
    if action not in ("BUY", "SELL"):
        return _out(False, "rejected", f"live gate: option_spread action {action!r} not supported")
    if not math.isfinite(qty) or qty <= 0 or qty != int(qty):
        return _out(False, "rejected", "live gate: quantity must be > 0")
    if not math.isfinite(limit) or not math.isfinite(claimed_risk) or limit <= 0 or claimed_risk <= 0:
        return _out(False, "rejected", "live gate: limit and debit_risk must be > 0")
    if tif not in ("DAY", "GTC"):
        return _out(False, "rejected", f"live gate: tif {tif} not supported (DAY/GTC)")
    qty = int(qty)
    legs, err = _parse_spread_legs(p)
    if err:
        return _out(False, "rejected", f"live gate: {err}")
    if (len(legs) == 1 and
            (action != "BUY" or legs[0]["side"] != "BUY" or legs[0]["ratio"] != 1)):
        return _out(False, "rejected",
                    "live gate: a single option leg must be a 1:1 BUY (naked short options stay disabled)")

    snapped = snap_combo_limit(limit, action, OPT_COMBO_TICK)
    if snapped <= 0:
        return _out(False, "rejected", f"live gate: limit {limit} snaps to {snapped:g} on the {OPT_COMBO_TICK:g} grid")

    # Cheap quantity veto before broker qualification; risk/direction are
    # derived only after exact qualified contracts are available below.
    if not _uncapped_options(acct) and qty > LIVE_MAX_OPT_CONTRACTS:
        return _out(False, "rejected",
                    f"live gate: {qty} spreads > LIVE_MAX_OPT_CONTRACTS {LIVE_MAX_OPT_CONTRACTS}")

    # --- qualify each leg; payload conId is a cross-check, never trusted alone ---
    qualified = []
    qualified_contracts = []
    for l in legs:
        c = Option(sym, l["expiry"], l["strike"], l["right"], "SMART", tradingClass=sym)
        got = ib.qualifyContracts(c)
        qualified_contract = got[0] if len(got) == 1 else None
        cid = int(getattr(qualified_contract, "conId", 0) or 0)
        if len(got) != 1 or not cid:
            return _out(False, "rejected",
                        f"live gate: leg {sym} {l['expiry']} {l['strike']:g}{l['right']} did not "
                        f"qualify to exactly one contract -- order ABORTED")
        if l["con_id"] and l["con_id"] != cid:
            return _out(False, "rejected",
                        f"live gate: leg {l['strike']:g}{l['right']} conId mismatch "
                        f"(payload {l['con_id']} vs qualified {cid}) -- stale snapshot? order ABORTED")
        qualified.append((cid, l["ratio"], l["side"]))
        qualified_contracts.append(qualified_contract)

    trusted, topology_error = _trusted_option_topology(
        action, snapped, qty, legs, qualified_contracts
    )
    if topology_error:
        return _out(False, "rejected", f"live gate: {topology_error}")
    risk = float(trusted["risk_usd"])
    portfolio_direction = trusted["portfolio_direction"]
    n_contracts = qty * len(legs)
    comm = OPT_COMM_PER_CONTRACT * n_contracts * 2
    calculated_unit_risk = (risk - comm) / (100.0 * qty)
    if abs(claimed_risk - calculated_unit_risk) > 0.011:
        return _out(False, "rejected",
                    f"live gate: claimed risk {claimed_risk:g} != calculated {calculated_unit_risk:g} per spread")
    if not _uncapped_options(acct):
        cap = _max_opt_risk(acct)
        if risk > cap:
            return _out(False, "rejected",
                        f"live gate: option risk ${risk:,.0f} exceeds ${cap:,.0f} ({acct} cap)")
    else:
        nlv = _nlv(ib, broker_account)
        if not nlv and p.get("risk_ack") is not True:
            return _out(False, "rejected",
                        "RISK_ACK_REQUIRED: option risk is uncapped and NLV is unavailable -- resend with approval",
                        fill={"needs_risk_ack": True, "est_risk": round(risk, 2)})
        if nlv and risk > 0.05 * nlv and p.get("risk_ack") is not True:
            bps = risk / nlv * 1e4
            return _out(False, "rejected",
                        f"RISK_ACK_REQUIRED: option max loss ${risk:,.0f} = {bps:.0f} bps of NLV -- resend with approval",
                        fill={"needs_risk_ack": True, "est_risk": round(risk, 2),
                              "est_bps": round(bps, 1), "nlv": round(nlv, 2)})

    order_contract = qualified_contracts[0] if len(qualified_contracts) == 1 else build_combo(sym, qualified)
    o = LimitOrder(action, qty, snapped)
    o.tif = tif
    o.account = broker_account
    guard_signal = _command_signal(p, "option-spread-parent")
    o.orderRef = guard_signal
    _ERRORS.clear()
    t = guarded_place_order(
        ib,
        order_contract,
        o,
        mutation_kind="entry",
        portfolio_direction=portfolio_direction,
        risk_usd=risk,
        signal_id=guard_signal,
        account=broker_account,
    )
    ib.sleep(3.0)
    st = t.orderStatus.status
    problem = _placement_problem([t], ib=ib)
    if problem:
        return _out(
            False,
            "unknown",
            f"live gate: option order lacks broker-live proof [{problem}]; "
            "VERIFY IN TWS AND DO NOT RETRY",
            fill={"order_id": t.order.orderId, "status": st},
        )
    legs_txt = " / ".join(f"{l['side'][0]}{l['strike']:g}{l['right']}" for l in legs)
    structure = "single" if len(legs) == 1 else "combo"
    return _out(True, "executed",
                f"LIVE {action} {qty}x {sym} {structure} [{legs_txt}] LMT {snapped:g} ({tif}) -> {st}",
                fill={"order_id": t.order.orderId, "perm_id": t.order.permId or 0, "status": st})

def _resolve_option_expiry(expiries, today, mode, min_dte=None, expiry=None):
    """Deterministic listed-expiry resolver used at the scheduled trigger."""
    valid = sorted(str(x).replace("-", "")[:8] for x in expiries
                   if str(x).replace("-", "")[:8].isdigit())
    if mode == "specific":
        wanted = str(expiry or "").replace("-", "")[:8]
        if wanted not in valid:
            raise ValueError(f"specific expiry {wanted or '?'} is not listed")
        return wanted
    if mode != "min_dte":
        raise ValueError("expiry_mode must be min_dte or specific")
    days = int(min_dte)
    for listed in valid:
        d = datetime.date(int(listed[:4]), int(listed[4:6]), int(listed[6:8]))
        if (d - today).days >= days:
            return listed
    raise ValueError(f"no listed expiry has at least {days} DTE")

def _select_delta_row(rows, right, target_delta, tolerance):
    candidates = []
    for row in rows or []:
        try:
            delta = abs(float(row.get("delta")))
            ask = float(row.get("ask"))
            con_id = int(row.get("con_id") or 0)
        except (TypeError, ValueError):
            continue
        if str(row.get("right") or "").upper() != right or not (ask > 0) or not con_id:
            continue
        candidates.append((abs(delta - target_delta), delta, row))
    if not candidates:
        raise ValueError(f"no quoted {right} contract has live delta, ask, and conId")
    miss, actual_delta, row = min(candidates, key=lambda item: (item[0], item[1]))
    if miss > tolerance:
        raise ValueError(f"nearest {right} delta {actual_delta:.3f} misses target {target_delta:.3f} by more than {tolerance:.3f}")
    if int(row.get("market_data_type") or 0) != 1:
        raise ValueError("selected option quote is not live market data")
    return row

def _market_option_quantity(premium_budget, ask):
    """Premium target excludes commissions; a MKT fill can exceed this estimate."""
    if not (premium_budget > 0 and ask > 0):
        return 0
    return int(math.floor(premium_budget / (ask * 100.0)))

def _do_dynamic_option_limit(ib, p, acct):
    from option_limit_pricing import capped_market_size, market_increments, fresh_live_ask, validate_intent
    try:
        validate_intent(p)
    except (ValueError, KeyError, TypeError) as exc:
        return _out(False, "rejected", str(exc))
    attempted = False
    sym = str(p.get("symbol") or "").upper().strip()
    broker_account = str(p.get("_broker_account") or "").strip()
    if not broker_account:
        return _out(False, "rejected", "live gate: exact broker account is unavailable")
    right = str(p.get("right") or "").upper()
    mode = str(p.get("expiry_mode") or "")
    try:
        target_delta = float(p.get("target_delta"))
        tolerance = float(p.get("delta_tolerance") or 0.03)
        budget = float(p.get("premium_budget"))
    except (TypeError, ValueError):
        return _out(False, "rejected", "live gate: delta/tolerance/premium budget must be numbers")
    if str(p.get("order_type") or "").upper() != "LMT" or str(p.get("tif") or "").upper() != "DAY":
        return _out(False, "rejected", "live gate: dynamic option intent must be LMT DAY")
    if str(acct or "").lower() not in OPTION_ACCOUNTS:
        return _out(False, "rejected", f"live gate: options execution is disabled for {acct}")
    if not sym or right not in ("P", "C"):
        return _out(False, "rejected", "live gate: valid symbol and P/C right required")
    if not 0.01 <= target_delta <= 0.50 or not 0 < tolerance <= 0.15 or (not math.isfinite(budget) or budget <= 0):
        return _out(False, "rejected", "live gate: invalid target delta, tolerance, or premium budget")
    if not _uncapped_options(acct) and budget > _max_opt_risk(acct):
        return _out(False, "rejected",
                    f"live gate: premium target ${budget:,.0f} exceeds ${_max_opt_risk(acct):,.0f} ({acct} cap)")
    if _uncapped_options(acct):
        nlv = _nlv(ib, broker_account)
        if (not nlv or budget > 0.05 * nlv) and p.get("risk_ack") is not True:
            return _out(False, "rejected",
                        "RISK_ACK_REQUIRED: scheduled option premium target is uncapped and NLV is unavailable or target exceeds 5%",
                        fill={"needs_risk_ack": True, "est_risk": round(budget, 2), "nlv": round(nlv, 2) if nlv else None})

    try:
        from option_workbench import _quote_chain

        underlying = Stock(sym, "SMART", "USD")
        if len(ib.qualifyContracts(underlying)) != 1 or not int(underlying.conId or 0):
            return _out(False, "rejected", f"live gate: could not qualify stock/ETF underlying {sym}")
        # Scheduled limit sizing requires live marks. No frozen/delayed fallback.
        ib.reqMarketDataType(1)
        [ut] = ib.reqTickers(underlying)
        spot = ut.marketPrice()
        if spot is None or not math.isfinite(spot) or spot <= 0:
            return _out(False, "rejected", f"live gate: no live spot quote for {sym}")
        if int(getattr(ut, "marketDataType", 0) or 0) != 1:
            return _out(False, "rejected", f"live gate: {sym} underlying quote is not live market data")
        params = ib.reqSecDefOptParams(underlying.symbol, "", underlying.secType, underlying.conId)
        if not params:
            return _out(False, "rejected", f"live gate: no option parameters for {sym}")
        standard = [x for x in params if x.tradingClass == sym] or params
        expiries = sorted(set().union(*(set(x.expirations) for x in standard)))
        strikes = sorted(set().union(*(set(x.strikes) for x in standard)))
        tc = sym if standard is not params else params[0].tradingClass
        today = datetime.date.today()
        expiry = _resolve_option_expiry(expiries, today, mode, p.get("min_dte"), p.get("expiry"))
        chain, chain_error = _quote_chain(ib, sym, tc, expiry, strikes, spot, today)
        if not chain:
            return _out(False, "rejected", f"live gate: chain unavailable ({chain_error or 'unknown'})")
        row = _select_delta_row(chain.get("strikes"), right, target_delta, tolerance)
        contract = Option(sym, expiry, float(row["strike"]), right, "SMART", tradingClass=tc)
        qualified = ib.qualifyContracts(contract)
        contract = qualified[0] if len(qualified) == 1 else contract
        cid = int(getattr(contract, "conId", 0) or 0)
        if len(qualified) != 1 or not cid or cid != int(row["con_id"]):
            return _out(False, "rejected", "live gate: selected option contract identity changed; order ABORTED")
        details = ib.reqContractDetails(contract)
        if len(details) != 1 or int(details[0].contract.conId) != cid:
            raise ValueError("exact option contract details required")
        bands = market_increments(ib, contract, details[0])
        quote_requested_at = datetime.datetime.now(datetime.timezone.utc)
        quotes = ib.reqTickers(contract)
        if len(quotes) != 1:
            raise ValueError("exact option quote required")
        quote = quotes[0]
        ask = fresh_live_ask(quote, cid, quote_requested_at)
        qty, limit = capped_market_size(budget, ask, bands, contract.multiplier)
        if not _uncapped_options(acct) and qty > LIVE_MAX_OPT_CONTRACTS:
            raise ValueError("option quantity exceeds the existing account cap")
        validate_intent(p)  # slow chain lookup must not cross the deadline
        trusted, topology_error = _trusted_option_topology(
            "BUY",
            limit,
            qty,
            [{
                "side": "BUY", "right": right, "expiry": expiry,
                "strike": float(row["strike"]), "ratio": 1,
                "con_id": cid,
            }],
            [contract],
        )
        if topology_error:
            return _out(False, "rejected", f"live gate: {topology_error}")
        estimated_risk = float(trusted["risk_usd"])
        if not _uncapped_options(acct) and estimated_risk > _max_opt_risk(acct):
            return _out(
                False,
                "rejected",
                f"live gate: limit-based option risk ${estimated_risk:,.0f} exceeds "
                f"${_max_opt_risk(acct):,.0f} ({acct} cap)",
            )

        order = LimitOrder("BUY", qty, limit)
        order.tif = "DAY"
        order.outsideRth = False
        order.account = broker_account
        order.orderRef = _command_signal(p, "dynamic-option-limit")
        estimated_premium = limit * 100.0 * qty
        _ERRORS.clear()
        validate_intent(p)
        fresh_live_ask(quote, cid, quote_requested_at)
        attempted = True
        trade = guarded_place_order(
            ib,
            contract,
            order,
            mutation_kind="entry",
            portfolio_direction=trusted["portfolio_direction"],
            risk_usd=estimated_risk,
            signal_id=order.orderRef,
            account=broker_account,
        )
        ib.sleep(3.0)
        status = trade.orderStatus.status
        if _ERRORS:
            return _out(False, "unknown",
                        f"live gate: option limit broker response requires reconciliation [{'; '.join(_ERRORS[-4:])}]",
                        fill={"order_id": trade.order.orderId, "status": status})
        actual_delta = abs(float(row["delta"]))
        filled = float(trade.orderStatus.filled or 0)
        avg_fill = float(trade.orderStatus.avgFillPrice or 0)
        if status not in {"Submitted", "PreSubmitted", "Filled"}:
            return _out(False, "unknown", f"Option limit outcome {status}; reconcile before retry",
                        fill={"order_id": trade.order.orderId, "status": status})
        return _out(True, "executed",
                    f"LIVE BUY {qty}x {sym} {expiry} {row['strike']:g}{right} LMT {limit:g} DAY; delta {actual_delta:.3f}, maximum premium ${estimated_premium:,.0f} -> {status}",
                    fill={"order_id": trade.order.orderId, "perm_id": trade.order.permId or 0,
                          "status": status, "filled": filled, "avg_fill": avg_fill or None,
                          "symbol": sym, "expiry": expiry, "strike": float(row["strike"]),
                          "right": right, "con_id": cid, "delta": actual_delta,
                          "ask_at_submit": ask, "limit": limit, "estimated_premium": round(estimated_premium, 2),
                          "premium_target": round(budget, 2), "quantity": qty})
    except ValueError as e:
        return _out(False, "unknown" if attempted else "rejected", f"scheduled option: {e}")
    except Exception as e:  # noqa: BLE001 -- no order unless every prior gate passed
        return _out(False, "unknown" if attempted else "rejected", f"dynamic option execution error: {type(e).__name__}: {e}")

def _fut_trading_class(sym):
    """tradingClass for a futures root from contract_reference.json (falls back
    to the symbol itself). Pins the contract to ONE class -- a bare COMEX 'SI'
    matches both SI (5,000 oz) and SIL (1,000 oz Micro) without it."""
    try:
        with open(os.path.join(_THIS_DIR, "contract_reference.json")) as f:
            ref = json.load(f)
        for r in ref:
            if sym in (str(r.get("symbol", "")).upper(), str(r.get("alias", "")).upper()):
                return str(r.get("trading_class") or "") or sym
    except Exception:  # noqa: BLE001
        pass
    return sym

def _nlv(ib, account):
    """One exact account's positive NetLiquidation, or ``None``."""
    expected = str(account or "").strip()
    if not expected:
        return None
    try:
        values = [
            float(row.value)
            for row in ib.accountSummary()
            if str(getattr(row, "account", "") or "").strip() == expected
            and str(getattr(row, "tag", "") or "") == "NetLiquidation"
        ]
    except Exception:  # noqa: BLE001
        return None
    if len(values) != 1 or not math.isfinite(values[0]) or values[0] <= 0:
        return None
    return values[0]

def _atr_estimate(ib, contract, sec_type):
    """(Wilder ATR(14), last close) from daily bars, or (None, None).

    CASH has no TRADES data on IDEALPRO -- use MIDPOINT. 45 calendar days
    comfortably covers the 15 daily bars the seed + smoothing need."""
    try:
        what = "MIDPOINT" if str(sec_type).upper() == "CASH" else "TRADES"
        bars = ib.reqHistoricalData(contract, endDateTime="", durationStr="45 D",
                                    barSizeSetting="1 day", whatToShow=what,
                                    useRTH=True, formatDate=1)
    except Exception:  # noqa: BLE001
        return None, None
    if not bars or len(bars) < 15:
        return None, None
    prev_close, trs = bars[0].close, []
    for b in bars[1:]:
        trs.append(max(b.high - b.low, abs(b.high - prev_close), abs(b.low - prev_close)))
        prev_close = b.close
    atr = sum(trs[:14]) / 14.0
    for tr in trs[14:]:
        atr = (atr * 13 + tr) / 14.0
    last_close = float(bars[-1].close or 0)
    return (atr, last_close) if atr > 0 and last_close > 0 else (None, None)

def _execution_deadline(value, clock):
    from zoneinfo import ZoneInfo
    raw = str(value).strip()
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}|\d{8}", raw):
        raise ValueError("use YYYY-MM-DD")
    date = datetime.datetime.strptime(raw.replace("-", ""), "%Y%m%d")
    when = datetime.datetime.combine(date.date(), datetime.time.fromisoformat(clock), ZoneInfo("America/New_York"))
    if when <= datetime.datetime.now(ZoneInfo("America/New_York")):
        raise ValueError("deadline has already passed")
    return when.strftime("%Y%m%d %H:%M:%S") + " US/Eastern"

def next_session_gat():
    """goodAfterTime string for the open of the NEXT trading session.

    Copied verbatim from eq_order_entry.next_session_gat (importing that module
    here would pull in its Sheets/staging dependencies); pitch_moo uses the same
    string for its day-2-armed stops.
    """
    import pandas as pd
    nxt = pd.Timestamp.now().normalize() + pd.offsets.BDay(1)
    return nxt.strftime("%Y%m%d") + " 09:30:00"

STOP_ARM_VALUES = ("fill", "next_session")
TIME_STOP_AT_CLOCK = {"close": "15:59:00", "open": "09:30:00"}

def _exit_timing(p):
    """(stop goodAfterTime or None, time-exit clock) from the optional stop_arm /
    time_stop_at fields. Absent = today's behavior (stop live at fill, time exit
    at 15:59). Unknown values raise ValueError so the command fails closed."""
    arm = p.get("stop_arm")
    arm = "fill" if arm in (None, "") else str(arm)
    if arm not in STOP_ARM_VALUES:
        raise ValueError(f"stop_arm must be 'fill' or 'next_session', got {p.get('stop_arm')!r}")
    at = p.get("time_stop_at")
    at = "close" if at in (None, "") else str(at)
    if at not in TIME_STOP_AT_CLOCK:
        raise ValueError(f"time_stop_at must be 'open' or 'close', got {p.get('time_stop_at')!r}")
    return (next_session_gat() if arm == "next_session" else None), TIME_STOP_AT_CLOCK[at]

def _do_exit_attach(ib, p, acct):
    """Attach a standalone closing OCA group (stop / target / time, any subset)
    to an existing position with nothing working against it. Sized to the full
    held quantity; never touches other orders."""
    try:
        stop = float(p["stop"]) if p.get("stop") not in (None, "") else None
        target = float(p["target"]) if p.get("target") not in (None, "") else None
    except (TypeError, ValueError):
        return _out(False, "rejected", "live gate: stop/target must be numbers")
    try:
        stop_gat, time_clock = _exit_timing(p)
    except ValueError as exc:
        return _out(False, "rejected", f"live gate: {exc}")
    time_stop = p.get("time_stop")
    time_gat = None
    if time_stop:
        try:
            time_gat = _execution_deadline(time_stop, time_clock)
        except ValueError as exc:
            return _out(False, "rejected", f"live gate: time_stop must be a future valid date ({exc})")
    if stop is None and target is None and not time_gat:
        return _out(False, "rejected",
                    "live gate: exit_attach needs at least one of stop/target/time_stop")
    if any(not math.isfinite(v) or v <= 0 for v in (stop, target) if v is not None):
        return _out(False, "rejected", "live gate: stop/target must be > 0")

    pos, err = _exact_position(ib, p)
    if err:
        return _out(False, "rejected", f"live gate: {err}")
    ref = pos.contract
    sec_type = str(getattr(ref, "secType", "")).upper()
    if sec_type not in {"STK", "CASH", "FUT"}:
        return _out(False, "rejected",
                    f"live gate: exit_attach supports only STK/CASH/FUT, not "
                    f"{sec_type or 'unknown'}; one-leg option closes can dismantle a hedge")
    # positions() contracts carry a BLANK exchange; stocks must SMART-route
    # (same 10311/201 failure class as the flatten path), FUT/CASH keep the
    # qualified venue.
    if sec_type == "STK":
        ref.exchange = "SMART"
    from execution_contracts import qualify_position
    try:
        pos = qualify_position(ib, pos)
    except (ValueError, BrokerMutationBlocked) as exc:
        return _out(False, "rejected", str(exc))
    ref = pos.contract
    live_position = float(pos.position)
    held = int(round(abs(live_position)))
    if held <= 0:
        return _out(False, "rejected", "live gate: position quantity is zero")
    close_action = "SELL" if live_position > 0 else "BUY"

    # Tick snap for FUT/CASH (IBKR rejects off-tick prices).
    if sec_type in ("FUT", "CASH") and (stop is not None or target is not None):
        try:
            from futures_sizing import snap_to_tick
        except Exception as e:  # noqa: BLE001
            return _out(False, "rejected", f"live gate: price snap module unavailable ({e})")
        details = ib.reqContractDetails(ref)
        min_tick = float(getattr(details[0], "minTick", 0) or 0) if len(details) == 1 else 0.0
        if not min_tick > 0:
            return _out(False, "rejected", "live gate: tick size unavailable; order ABORTED")
        if stop is not None:
            stop = snap_to_tick(stop, min_tick)
        if target is not None:
            target = snap_to_tick(target, min_tick)

    # Side ordering vs each other and, when a mark is readable, vs the market --
    # a wrong-side STP or LMT would fill the instant it reaches the exchange.
    long_pos = live_position > 0
    if stop is not None and target is not None:
        if long_pos and not stop < target:
            return _out(False, "rejected", "live gate: long position needs stop < target")
        if not long_pos and not target < stop:
            return _out(False, "rejected", "live gate: short position needs target < stop")
    mark = 0.0
    try:
        tickers = ib.reqTickers(ref)
        if tickers:
            tk = tickers[0]
            for v in (tk.marketPrice(), tk.last, tk.close):
                v = _px(v)
                if v:
                    mark = v
                    break
    except Exception:  # noqa: BLE001
        mark = 0.0
    if mark:
        if stop is not None and ((long_pos and stop >= mark) or (not long_pos and stop <= mark)):
            return _out(False, "rejected",
                        f"live gate: stop {stop} is on the wrong side of the market ({mark:.4f}) "
                        "-- it would trigger immediately")
        if target is not None and ((long_pos and target <= mark) or (not long_pos and target >= mark)):
            return _out(False, "rejected",
                        f"live gate: target {target} is on the wrong side of the market ({mark:.4f}) "
                        "-- it would fill immediately")

    # Nothing may already be working on this contract: attaching alongside
    # working closing exits over-covers; alongside a pending same-direction
    # entry, the full-size legs would over-cover once it fills.
    try:
        working = _orders_for_contract(ib, ref, p.get("_broker_account"))
    except (ValueError, BrokerMutationBlocked) as exc:
        return _out(False, "rejected", f"live gate: working-order proof failed ({exc})")
    if working:
        closing = [t for t in working if str(t.order.action).upper() == close_action]
        label = ("closing exit(s) already working -- cancel or modify them instead"
                 if closing else "same-direction entry/add order already working")
        return _out(False, "rejected", f"live gate: {len(working)} {label}")

    account = getattr(pos, "account", None)
    oca = None
    orders = []
    if target is not None:
        o = LimitOrder(close_action, held, target)
        orders.append(("TARGET", o))
    if stop is not None:
        o = StopOrder(close_action, held, stop)
        if stop_gat:
            o.goodAfterTime = stop_gat  # stop_arm=next_session
        if sec_type == "FUT":
            o.outsideRth = True         # survive the overnight session (entry-bracket convention)
        orders.append(("STOP", o))
    if time_gat:
        o = MarketOrder(close_action, held)
        o.goodAfterTime = time_gat
        o.outsideRth = True
        orders.append(("TIME", o))
    # Standalone group (no parent): each leg transmits itself, matching the
    # flatten path's exit restore (_place_exit_legs with parent_id=0).
    _ERRORS.clear()
    placed = []
    for label, o in orders:
        o.orderId = ib.client.getReqId()
        if oca is None:
            oca = f"OCA_{o.orderId}"
        if len(orders) > 1:
            o.ocaGroup = oca
            o.ocaType = 1
        o.tif = "GTC"
        if p.get("outside_rth") and label != "TIME":
            o.outsideRth = True
        if account:
            o.account = account
        placed.append(
            guarded_place_order(
                ib,
                ref,
                o,
                mutation_kind="exit",
                signal_id=_command_signal(p, f"exit-attach:{label.lower()}"),
                account=p.get("_broker_account"),
            )
        )
    ib.sleep(2.0)
    problem = _placement_problem(placed, ib=ib)
    legs_txt = " ".join(x for x in (
        f"stop {stop}" if stop is not None else "",
        f"target {target}" if target is not None else "",
        f"time {time_stop}" if time_gat else "") if x)
    if problem:
        return _out(False, "unknown",
                    f"exit_attach placement problem [{problem}] -- VERIFY IN TWS: "
                    f"{close_action} {held} {ref.symbol} [{legs_txt}]; DO NOT RETRY",
                    fill={"order_ids": _placed_ids(placed)})
    return _out(True, "executed",
                f"LIVE attached exits to {ref.symbol} ({acct}): {close_action} {held} [{legs_txt}]",
                fill={"order_ids": _placed_ids(placed)})

def _do_entry_bracket(ib, p, acct):
    sym = str(p.get("symbol", "")).upper()
    broker_account = str(p.get("_broker_account") or "").strip()
    if not broker_account:
        return _out(False, "rejected", "live gate: exact broker account is unavailable")
    action = str(p.get("action", "")).upper()
    sec_type = str(p.get("sec_type", "STK")).upper()
    entry_type = str(p.get("entry_type") or "LMT").upper()
    try:
        qty_raw = float(p.get("quantity"))
        entry = float(p.get("entry"))
        stop = float(p["stop"]) if p.get("stop") not in (None, "") else None
        target = float(p["target"]) if p.get("target") not in (None, "") else None
        entry_cap = float(p["entry_cap"]) if p.get("entry_cap") not in (None, "") else None
    except (TypeError, ValueError):
        return _out(False, "rejected", "live gate: entry/entry_cap/stop/target/qty must be numbers")
    if not math.isfinite(qty_raw) or qty_raw <= 0 or qty_raw != int(qty_raw):
        return _out(False, "rejected", "live gate: qty must be a whole number > 0")
    qty = int(qty_raw)
    if action not in ("BUY", "SELL"):
        return _out(False, "rejected", "live gate: action must be BUY/SELL")
    if not sym:
        return _out(False, "rejected", "live gate: symbol required")
    if sec_type not in ("STK", "FUT", "CASH"):
        return _out(False, "rejected",
                    f"live gate: sec_type {sec_type} not supported (STK/FUT/CASH)")
    if entry_type not in ("LMT", "STP_LMT", "MKT", "MOO", "MOC"):
        return _out(False, "rejected", f"live gate: unsupported entry_type {entry_type}")
    if entry_type == "MOC" and sec_type != "STK":
        return _out(False, "rejected", "live gate: MOC entry supports stocks only")
    if entry_type == "MOO" and sec_type == "CASH":
        return _out(False, "rejected", "live gate: MOO entry does not support FX")
    if entry_type == "STP_LMT" and sec_type != "STK":
        return _out(False, "rejected", "live gate: STP_LMT entry supports stocks only")
    if entry_type == "STP_LMT" and entry_cap is None:
        return _out(False, "rejected", "live gate: STP_LMT requires entry_cap (the limit price)")
    if entry_type != "STP_LMT" and entry_cap is not None:
        return _out(False, "rejected", "live gate: entry_cap applies to STP_LMT only")
    order_ref = None
    if str(p.get("strategy") or "").strip():
        order_ref, ref_err = build_order_ref(sym, action, p.get("strategy"), p.get("ref_date"))
        if ref_err:
            return _out(False, "rejected", f"live gate: {ref_err}")
    if any(not math.isfinite(v) or v <= 0 for v in
           (entry, entry_cap, stop, target) if v is not None):
        return _out(False, "rejected", "live gate: entry/entry_cap/stop/target must be > 0")

    # --- Resolve contract + $-multiplier (+ tick for FUT/CASH) per instrument ---
    if sec_type == "FUT":
        try:
            from futures_sizing import get_spec, snap_to_tick
        except Exception as e:  # noqa: BLE001
            return _out(False, "rejected", f"live gate: futures module unavailable ({e})")
        fut_expiry = str(p.get("fut_expiry") or "").strip()
        if not (len(fut_expiry) in (6, 8) and fut_expiry.isdigit()):
            return _out(False, "rejected", "live gate: FUT requires fut_expiry YYYYMM (or YYYYMMDD)")
        try:
            spec = get_spec(sym)
        except KeyError:
            spec = None
        exch = str(p.get("exchange") or (spec.exchange if spec else "")).upper().strip()
        if exch not in ALLOWED_FUTURES_EXCHANGES:
            return _out(False, "rejected",
                        "live gate: FUT exchange must be CME, CBOT, NYMEX, or COMEX")
        if spec and exch != str(spec.exchange).upper():
            return _out(False, "rejected",
                        f"live gate: {sym} is mapped to {spec.exchange}, not {exch}")
        ib_symbol = str(p.get("fut_ib_symbol") or (spec.symbol if spec else sym)).upper().strip()
        trading_class = str(p.get("fut_trading_class") or
                            (_fut_trading_class(sym) if spec else "")).upper().strip()
        if not ib_symbol or not trading_class:
            return _out(False, "rejected",
                        "live gate: unresolved FUT needs exact IB symbol and trading class")
        try:
            expected_mult = float(p.get("fut_multiplier") or (spec.multiplier if spec else 0))
            expected_tick = float(p.get("fut_min_tick") or (spec.min_tick if spec else 0))
        except (TypeError, ValueError):
            expected_mult = expected_tick = 0.0
        if expected_mult <= 0 or expected_tick <= 0:
            return _out(False, "rejected",
                        "live gate: unresolved FUT multiplier/tick is missing; resolve it from IBKR again")
        currency = str(p.get("currency") or "USD")
        # Build with the exact IB root AND trading class returned by discovery;
        # a bare root can span multiple sizes (for example SI and SIL).
        c = Future(ib_symbol, fut_expiry, exch, currency=currency,
                   tradingClass=trading_class)
        inst_desc = f"{sym} FUT {fut_expiry} {exch} tradingClass {c.tradingClass}"
    elif sec_type == "CASH":
        currency = str(p.get("currency") or "USD").upper().strip()
        if len(sym) != 3 or not sym.isalpha():
            return _out(False, "rejected",
                        "live gate: CASH symbol must be a 3-letter base currency")
        if len(currency) != 3 or not currency.isalpha() or currency == sym:
            return _out(False, "rejected",
                        "live gate: CASH currency must be a different 3-letter quote currency")
        if "USD" not in (sym, currency):
            return _out(False, "rejected",
                        "live gate: CASH entry supports USD pairs only initially")
        mult = 1.0
        c = Forex(f"{sym}{currency}")
        inst_desc = f"{sym}/{currency} CASH IDEALPRO"
    else:
        mult = 1.0
        c = Stock(sym, "SMART", "USD")
        inst_desc = f"{sym} STK SMART"

    qualified = ib.qualifyContracts(c)
    if len(qualified) != 1 or not int(getattr(qualified[0], "conId", 0) or 0):
        return _out(False, "rejected",
                    f"live gate: contract did not qualify to exactly one match "
                    f"({inst_desc}) -- got {len(qualified)}; order ABORTED")
    c = qualified[0]
    if sec_type == "FUT":
        details = ib.reqContractDetails(c)
        if len(details) != 1:
            return _out(False, "rejected",
                        f"live gate: qualified FUT returned {len(details)} detail rows; order ABORTED")
        try:
            mult = float(getattr(details[0].contract, "multiplier", 0) or
                         getattr(c, "multiplier", 0) or 0)
            min_tick = float(getattr(details[0], "minTick", 0) or 0)
        except (TypeError, ValueError):
            mult = min_tick = 0.0
        actual_class = str(getattr(c, "tradingClass", "") or "").upper()
        if mult <= 0 or min_tick <= 0:
            return _out(False, "rejected",
                        "live gate: qualified FUT multiplier/tick unavailable; order ABORTED")
        if actual_class != trading_class:
            return _out(False, "rejected",
                        f"live gate: FUT trading-class mismatch ({trading_class} vs {actual_class}); order ABORTED")
        if abs(mult - expected_mult) > max(1e-9, abs(mult) * 1e-9):
            return _out(False, "rejected",
                        f"live gate: FUT multiplier changed ({expected_mult:g} vs IBKR {mult:g}); resolve again")
        if abs(min_tick - expected_tick) > max(1e-9, abs(min_tick) * 1e-9):
            return _out(False, "rejected",
                        f"live gate: FUT tick changed ({expected_tick:g} vs IBKR {min_tick:g}); resolve again")
        entry = snap_to_tick(entry, min_tick)
        if stop is not None:
            stop = snap_to_tick(stop, min_tick)
        if target is not None:
            target = snap_to_tick(target, min_tick)
    elif sec_type == "CASH":
        details = ib.reqContractDetails(c)
        min_tick = float(getattr(details[0], "minTick", 0) or 0) if len(details) == 1 else 0.0
        if not min_tick > 0:
            return _out(False, "rejected",
                        f"live gate: {sym}/{currency} CASH tick size unavailable; order ABORTED")
        try:
            from futures_sizing import snap_to_tick
        except Exception as e:  # noqa: BLE001
            return _out(False, "rejected", f"live gate: price snap module unavailable ({e})")
        entry = snap_to_tick(entry, min_tick)
        if stop is not None:
            stop = snap_to_tick(stop, min_tick)
        if target is not None:
            target = snap_to_tick(target, min_tick)

    # --- Price ordering on the FINAL (tick-snapped) prices ---
    # ``worst`` is the worst acceptable fill. Every entry type with a single
    # parent price fills at (or through) ``entry``; STP_LMT can fill anywhere in
    # [trigger, cap], so its worst case is the CAP. Sizing, caps and the target
    # comparison below all read ``worst`` -- reading ``entry`` there would let a
    # wide cap fill through its own target and undercount risk by the cap width.
    # NOTE: STP_LMT is STK-only (gated above), which is why the FUT/CASH
    # tick-snap blocks never snap entry_cap. Relaxing that gate means snapping
    # the cap in both blocks too.
    worst = entry_cap if entry_cap is not None else entry
    if action == "BUY":
        if entry_cap is not None and not entry < entry_cap:
            return _out(False, "rejected",
                        "live gate: BUY STP_LMT needs trigger < cap (post tick-snap)")
        if not ((stop is None or stop < entry) and (target is None or worst < target)):
            return _out(False, "rejected",
                        "live gate: BUY needs stop < entry and worst fill < target (post tick-snap)")
    if action == "SELL":
        if entry_cap is not None and not entry_cap < entry:
            return _out(False, "rejected",
                        "live gate: SELL STP_LMT needs cap < trigger (post tick-snap)")
        if not ((stop is None or entry < stop) and (target is None or target < worst)):
            return _out(False, "rejected",
                        "live gate: SELL needs entry < stop and target < worst fill (post tick-snap)")

    # --- Multiplier-aware caps (share-count vs contract-count; notional carries mult) ---
    if sec_type == "FUT":
        if not _uncapped_futures(acct) and qty > LIVE_MAX_FUT_CONTRACTS:
            return _out(False, "rejected",
                        f"live gate: {qty} contracts > LIVE_MAX_FUT_CONTRACTS {LIVE_MAX_FUT_CONTRACTS}")
    elif LIVE_MAX_QTY > 0 and qty > LIVE_MAX_QTY:
        return _out(False, "rejected", f"live gate: qty {qty} > LIVE_MAX_QTY {LIVE_MAX_QTY:g}")
    if sec_type == "CASH":
        notional, stop_risk_value = _fx_usd_exposure(
            sym,
            currency,
            qty,
            worst,
            stop if stop is not None else worst,
        )
    else:
        notional = qty * worst * mult
        stop_risk_value = (
            abs(worst - stop) * qty * mult if stop is not None else 0.0
        )
    guard_risk_usd = stop_risk_value if stop_risk_value > 0 else None
    if sec_type != "CASH" and not (sec_type == "FUT" and _uncapped_futures(acct)):
        max_notional = _max_notional(acct)
        if notional > max_notional:
            return _out(False, "rejected",
                        f"live gate: notional {notional:.0f} > {max_notional:.0f} ({acct} cap)")

    # --- Uncapped-primary large-risk acknowledgement (NOT a cap) ---
    # Stopped futures over 5% NLV get a second explicit approval. Stopless
    # futures continue through the independent 2xATR acknowledgement below.
    if sec_type == "FUT" and _uncapped_futures(acct) and stop is not None:
        stop_risk = abs(worst - stop) * qty * mult
        nlv = _nlv(ib, broker_account)
        ack = p.get("risk_ack") is True
        if not nlv and not ack:
            return _out(False, "rejected",
                        "RISK_ACK_REQUIRED: futures risk is uncapped and NLV is unavailable -- resend with approval",
                        fill={"needs_risk_ack": True, "est_risk": round(stop_risk, 2)})
        if nlv and stop_risk > 0.05 * nlv and not ack:
            bps = stop_risk / nlv * 1e4
            return _out(False, "rejected",
                        f"RISK_ACK_REQUIRED: futures stop risk ${stop_risk:,.0f} = {bps:.0f} bps of NLV -- resend with approval",
                        fill={"needs_risk_ack": True, "est_risk": round(stop_risk, 2),
                              "est_bps": round(bps, 1), "nlv": round(nlv, 2)})

    # --- Unprotected-entry approval gate (NOT a cap; 2026-07-27) ---
    # No stop leg -> estimate risk as 2 x ATR(14) x notional and require an
    # explicit risk_ack above RISK_ACK_BPS of NLV. The RISK_ACK_REQUIRED tag +
    # fill.needs_risk_ack are the site's re-prompt contract -- keep both stable.
    if stop is None:
        ack = p.get("risk_ack") is True
        atr, last_close = _atr_estimate(ib, c, sec_type)
        nlv = _nlv(ib, broker_account)
        if atr and last_close and nlv:
            if sec_type == "CASH":
                atr_frac = atr / last_close
                risk = 2.0 * atr_frac * notional
            else:
                risk = 2.0 * atr * qty * mult
            guard_risk_usd = risk
            bps = risk / nlv * 1e4
            if bps > RISK_ACK_BPS and not ack:
                return _out(False, "rejected",
                            f"RISK_ACK_REQUIRED: unprotected entry est. risk ${risk:,.0f} "
                            f"= {bps:.0f} bps of NLV (2xATR basis) > {RISK_ACK_BPS:.0f} bps "
                            "-- resend with approval",
                            fill={"needs_risk_ack": True, "est_risk": round(risk, 2),
                                  "est_bps": round(bps, 1), "nlv": round(nlv, 2)})
        elif not ack:
            return _out(False, "rejected",
                        "RISK_ACK_REQUIRED: unprotected entry and the 2xATR risk estimate "
                        "is unavailable (ATR/NLV) -- resend with approval",
                        fill={"needs_risk_ack": True})

    # --- Timing legs ---
    try:
        stop_gat, time_clock = _exit_timing(p)
    except ValueError as exc:
        return _out(False, "rejected", f"live gate: {exc}")
    time_stop = p.get("time_stop")
    time_gat = None
    if time_stop:
        try:
            time_gat = _execution_deadline(time_stop, time_clock)
        except ValueError as exc:
            return _out(False, "rejected", f"live gate: time_stop must be a future valid date ({exc})")
    expiry = p.get("expiry")
    parent_gtd = None
    if expiry:
        if entry_type not in ("LMT", "STP_LMT"):
            return _out(False, "rejected", "live gate: entry expiry applies to LMT/STP_LMT only")
        try:
            parent_gtd = _execution_deadline(expiry, "16:00:00")
        except ValueError as exc:
            return _out(False, "rejected", f"live gate: expiry must be a future valid date ({exc})")

    # --- Optional scale-out: TWO independent single-target chains ---------------
    # Never one parent with a partial-size target child: the broker forces a
    # partial-size bracket child back up to the parent quantity (the bug
    # order_staging._split_scaleout_for_primary was written to sidestep). So a
    # scale-out is two ordinary brackets whose share counts sum to `qty`.
    #   near = round(qty * frac) shares, target = scaleout['target']
    #   far  = the remainder,            target = the payload's `target` (may be None)
    # Legs are tagged |near / |far on the orderRef, the same tranche convention
    # eq_order_entry.signal_ref uses, so downstream can tell them apart.
    scaleout = p.get("scaleout") or None
    near_qty = near_target = None
    if scaleout:
        if not isinstance(scaleout, dict):
            return _out(False, "rejected", "live gate: scaleout must be an object")
        try:
            frac = float(scaleout.get("frac"))
            near_target = float(scaleout["target"]) if scaleout.get("target") not in (None, "") else None
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: scaleout frac/target must be numbers")
        if not 0 < frac < 1:
            return _out(False, "rejected", "live gate: scaleout frac must be between 0 and 1")
        if near_target is None:
            return _out(False, "rejected", "live gate: scaleout needs a target for the near leg")
        if action == "BUY" and not worst < near_target:
            return _out(False, "rejected",
                        "live gate: BUY scaleout needs worst fill < near target")
        if action == "SELL" and not near_target < worst:
            return _out(False, "rejected",
                        "live gate: SELL scaleout needs near target < worst fill")
        near_qty = int(round(qty * frac))
        if near_qty < 1 or qty - near_qty < 1:
            # A tranche that rounds below one share is no split at all, not an
            # error -- same convention as the OVS scale-out.
            scaleout, near_qty, near_target = None, None, None

    # Do NOT pin account to managedAccounts()[0] -- the working entry scripts
    # (eq_order_entry.py / pa_order_entry.py) never set order.account. The
    # connection is already bound to the right terminal; pinning [0] misroutes on
    # a multi-account / FA login (same bug class as the flatten close). Pass None
    # so each leg routes to the connection's default account. FUT protective stop
    # goes outsideRth so it survives the overnight session. CASH regular trading
    # hours already span the nearly-24h IDEALPRO session.
    chains = ([(near_qty, near_target, "near"), (qty - near_qty, target, "far")]
              if scaleout else [(qty, target, "")])
    trades, chain_txt = [], []
    for cqty, ctarget, tranche in chains:
        ref = f"{order_ref}|{tranche}" if (order_ref and tranche) else order_ref
        guard_signal = _command_signal(p, f"entry-parent:{tranche or 'all'}")
        parent, children = build_bracket(action, cqty, entry, stop, ctarget, broker_account,
                                         ib.client.getReqId, time_gat, parent_gtd,
                                         stop_outside_rth=(sec_type == "FUT"),
                                         entry_type=entry_type, entry_cap=entry_cap,
                                         order_ref=ref, stop_gat=stop_gat)
        placed = [
            guarded_place_order(
                ib,
                c,
                parent,
                mutation_kind="entry",
                portfolio_direction="long" if action == "BUY" else "short",
                risk_usd=(
                    guard_risk_usd * cqty / qty
                    if guard_risk_usd is not None
                    else None
                ),
                signal_id=guard_signal,
                account=broker_account,
            )
        ]
        for child_index, child in enumerate(children, start=1):
            placed.append(
                guarded_place_order(
                    ib,
                    c,
                    child,
                    mutation_kind="protective",
                    signal_id=(
                        f"{guard_signal}|child:{child_index}:"
                        f"{str(child.orderType).lower()}"
                    ),
                    account=broker_account,
                )
            )
        trades.extend(placed)
        stop_txt = f"stop {stop}" if stop is not None else "NO STOP"
        tgt_txt = f" tgt {ctarget}" if ctarget is not None else " NO TGT"
        tm_txt = f" time {time_stop}" if time_gat else ""
        legs = (f"bracket[{stop_txt}{tgt_txt}{tm_txt}]" if children
                else "UNPROTECTED (no exit legs)")
        chain_txt.append(f"{tranche + ' ' if tranche else ''}{cqty} {legs}")
    ib.sleep(2.0)
    problem = _placement_problem(trades, ib=ib)
    if problem:
        return _out(
            False,
            "unknown",
            f"live gate: entry bracket lacks complete broker-live proof [{problem}]; "
            "VERIFY IN TWS AND DO NOT RETRY",
            fill={
                "order_ids": [t.order.orderId for t in trades],
                "statuses": [
                    str(getattr(t.orderStatus, "status", "") or "")
                    for t in trades
                ],
                "chains": len(chains),
            },
        )
    entry_tif = "OPG" if entry_type == "MOO" else f"GTD {expiry}" if parent_gtd else "DAY"
    entry_txt = (f"LMT {entry}" if entry_type == "LMT"
                 else f"STP LMT trig {entry} cap {entry_cap}" if entry_type == "STP_LMT"
                 else f"{entry_type} (risk ref {entry})")
    inst = (f"{sym} FUT {p.get('fut_expiry')}" if sec_type == "FUT"
            else f"{sym}/{currency} CASH" if sec_type == "CASH" else sym)
    ref_txt = f" ref {order_ref}" if order_ref else ""
    return _out(True, "executed",
                f"LIVE {action} {qty} {inst} {entry_txt} ({entry_tif}) "
                f"{' + '.join(chain_txt)}{ref_txt} -> {trades[0].orderStatus.status}",
                fill={"order_ids": [t.order.orderId for t in trades],
                      "parent_status": trades[0].orderStatus.status,
                      "chains": len(chains)})

def _prepare_position_action_add(ib, p, acct, *, partial):
    """Independent live validation shared by both fast position handlers."""
    import position_actions
    pos, err = _exact_position(ib, p)
    if err:
        return None, err
    ref = pos.contract
    if str(getattr(ref, "secType", "")).upper() != "STK":
        return None, "fast trim/re-add and add actions are stock-only initially"
    try:
        expected = float(p.get("expected_position"))
    except (TypeError, ValueError):
        return None, "expected_position is required and must be a number"
    live_position = float(pos.position)
    if expected != live_position:
        return None, f"stale position: expected {expected:g}, live {live_position:g}"
    held = int(round(abs(live_position)))
    qty, err = _fast_qty(held, p, partial=partial)
    if err:
        return None, err
    close_action = "SELL" if live_position > 0 else "BUY"
    entry_action = "BUY" if live_position > 0 else "SELL"
    avg_cost = float(getattr(pos, "avgCost", 0) or 0)
    if avg_cost <= 0:
        return None, "live average cost unavailable"

    targets = _orders_for_contract(ib, ref, p.get("_broker_account"))
    entries = [t for t in targets if str(t.order.action).upper() == entry_action]
    if entries:
        return None, f"{len(entries)} same-direction entry/add order(s) already working"
    exits = [t for t in targets if str(t.order.action).upper() == close_action]
    legs, err = _capture_exit_legs(exits, close_action)
    if err:
        return None, err
    err = position_actions.validate_topology(legs)
    if err:
        return None, err

    # Both resulting bracket shapes must be representable before any live action.
    totals = [held - qty]
    if partial and p.get("readd", True):
        totals.append(qty)
    if not partial:
        totals = [qty]
    for total in totals:
        err = position_actions.validate_total(legs, total)
        if err:
            return None, err

    adds_exposure = (not partial) or bool(p.get("readd", True))
    if adds_exposure:
        if LIVE_MAX_QTY > 0 and qty > LIVE_MAX_QTY:
            return None, f"add qty {qty} > LIVE_MAX_QTY {LIVE_MAX_QTY:g}"
        max_notional = _max_notional(acct)
        if qty * avg_cost > max_notional:
            return None, (f"add notional {qty * avg_cost:.0f} > {max_notional:.0f} "
                          f"({acct} cap)")
    return {
        "pos": pos, "ref": ref, "held": held, "qty": qty,
        "close_action": close_action, "entry_action": entry_action,
        "avg_cost": avg_cost, "exits": exits, "legs": legs,
        "account": getattr(pos, "account", None),
    }, None

def _fast_guard_risk_usd(ctx, qty):
    """Conservative stress risk for a stock add/re-add."""
    for leg in ctx["legs"]:
        if str(leg.get("order_type") or "").upper().startswith("STP"):
            try:
                stop = float(leg.get("aux"))
            except (TypeError, ValueError):
                continue
            if stop > 0:
                return abs(ctx["avg_cost"] - stop) * qty
    # A scheduled exit has no price-defined loss. Reserve full notional rather
    # than invent a smaller risk number.
    return ctx["avg_cost"] * qty

def _do_add_to_position(ib, p, acct, host, port, main_cid):
    import position_actions
    return position_actions.run(globals(), ib, p, acct, host, port, main_cid, adding=True)

def _do_close_only(ib, p):
    """Close a bare position without touching working orders.

    Any STK / CASH / FUT position qualifies (2026-09-03).  This used to be
    limited to the SPY/QQQ/IWM/DIA equity-index clusters, which was a holdover
    from the Legend reservation-guard rollout rather than a property of the
    close: `guarded_place_order` handles non-cluster symbols on every other
    path (eq_order_entry places the whole systematic book through it), and the
    safety that matters here is the bare-position rule below, not cluster
    membership.  `_cluster_symbol` is still CALLED so its validation of mapped
    equity-index futures (exchange + expiry present) keeps firing; only the
    "not a cluster symbol" rejection is gone.

    It refuses to place alongside any active order on the exact
    account/contract, so a second close cannot reverse the position while the
    first is still working.  A protected position wanting a partial close goes
    through close_resize, which shrinks the exits first.
    """
    pos, err = _exact_position(ib, p)
    if err:
        return _out(False, "rejected", f"live gate: {err}")
    sec_type = str(getattr(pos.contract, "secType", "") or "").upper()
    if sec_type not in {"STK", "CASH", "FUT"}:
        return _out(
            False,
            "rejected",
            f"live gate: close_only is disabled for {sec_type or 'unknown'} "
            "positions because closing one leg can dismantle a hedged structure",
        )
    try:
        from execution_contracts import qualify_position
        pos = qualify_position(ib, pos)
        _cluster_symbol(pos.contract)   # still validates exact exchange and expiry
    except (ValueError, BrokerMutationBlocked) as exc:
        return _out(False, "rejected", f"live gate: {exc}")

    held = int(round(abs(float(pos.position))))
    raw_qty = p.get("qty")
    if raw_qty not in (None, ""):
        try:
            qty_f = float(raw_qty)
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: qty must be a number")
        if qty_f <= 0 or qty_f != int(qty_f):
            return _out(False, "rejected", "live gate: qty must be a whole number > 0")
        qty = int(qty_f)
    else:
        try:
            fraction = float(p.get("fraction", 1.0) or 1.0)
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: fraction must be a number")
        if fraction <= 0:
            return _out(False, "rejected", "live gate: fraction must be > 0")
        qty = int(math.floor(held * fraction + 0.5))
    if qty <= 0:
        return _out(False, "rejected", "live gate: resolved close quantity is zero")
    if qty > held:
        return _out(False, "rejected",
                    f"live gate: close qty {qty} exceeds held {held} {p.get('symbol', '')}")

    close_action = "SELL" if float(pos.position) > 0 else "BUY"
    requested_action = str(p.get("action") or "").upper()
    if requested_action not in ("BUY", "SELL"):
        return _out(False, "rejected", "live gate: close action BUY or SELL is required")
    if requested_action != close_action:
        return _out(False, "rejected",
                    f"live gate: {requested_action} would add to the live position; "
                    f"required closing action is {close_action}")

    order_type = str(p.get("order_type") or "MKT").upper()
    if order_type not in ("MKT", "LMT"):
        return _out(False, "rejected", f"live gate: unsupported close order_type {order_type}")
    outside_rth = bool(p.get("outside_rth"))
    if outside_rth and order_type != "LMT":
        return _out(False, "rejected",
                    "live gate: outside-RTH close must be a LMT (IBKR ignores MKT outside RTH)")
    limit = p.get("limit")
    if order_type == "LMT":
        try:
            limit = float(limit)
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: LMT close needs a limit price")
        if not (0 < limit < 1e9):
            return _out(False, "rejected", "live gate: LMT close needs a positive limit price")
    tif = str(p.get("tif") or "DAY").upper()
    if tif not in ("DAY", "GTC"):
        return _out(False, "rejected", f"live gate: unsupported tif {tif}")
    if order_type == "MKT":
        tif = "DAY"

    contract = pos.contract
    if str(getattr(contract, "secType", "")).upper() == "STK":
        contract.exchange = "SMART"
    ib.qualifyContracts(contract)

    # Re-read immediately before transmission.  The browser's action must still
    # close the live direction and its size must still fit the live holding.
    live, err = _exact_position(ib, p)
    if err:
        return _out(False, "rejected", f"live gate: {err}")
    live_held = int(round(abs(float(live.position))))
    live_close_action = "SELL" if float(live.position) > 0 else "BUY"
    if requested_action != live_close_action:
        return _out(False, "rejected",
                    f"live gate: position direction changed; {requested_action} is no longer "
                    f"the closing action ({live_close_action} required)")
    if qty > live_held:
        return _out(False, "rejected",
                    f"live gate: close qty {qty} exceeds current held {live_held} "
                    f"{p.get('symbol', '')}")
    try:
        working = _orders_for_contract(ib, contract, p.get("_broker_account"))
    except (ValueError, BrokerMutationBlocked) as exc:
        return _out(False, "rejected", f"live gate: {exc}")
    if working:
        return _out(
            False,
            "rejected",
            f"live gate: {len(working)} working order(s) already exist on the exact "
            "account/contract; close_only is restricted to bare positions -- use "
            "close_resize for a partial close (it shrinks the exits first) or "
            "flatten to cancel them and close",
        )

    if order_type == "LMT":
        order = LimitOrder(requested_action, qty, limit)
        if outside_rth:
            order.outsideRth = True
    else:
        order = MarketOrder(requested_action, qty)
    order.tif = tif
    if getattr(live, "account", None):
        order.account = live.account

    _ERRORS.clear()
    trade = guarded_place_order(
        ib,
        contract,
        order,
        mutation_kind="exit",
        signal_id=_command_signal(p, "close-only"),
        account=p.get("_broker_account"),
    )
    for _ in range(12 if order_type == "MKT" else 4):
        ib.sleep(1.0)
        if trade.orderStatus.status in ("Filled", "Cancelled", "ApiCancelled", "Inactive"):
            break
    status = trade.orderStatus.status
    desc = (f"{order_type}{f' @ {limit:g}' if order_type == 'LMT' else ''}"
            f"{' outsideRTH' if outside_rth else ''} ({tif})")
    fill = {"order_id": trade.order.orderId, "status": status,
            "filled": trade.orderStatus.filled,
            "avg_fill": trade.orderStatus.avgFillPrice,
            "working_orders_untouched": True}
    if order_type == "MKT" and status != "Filled":
        errors = "; ".join(_ERRORS[-4:]) or "no IB error captured"
        terminal = status in ("Cancelled", "ApiCancelled", "Inactive")
        state = "rejected" if terminal and not float(trade.orderStatus.filled or 0) else "unknown"
        retry = "" if terminal else "; order may still fill -- DO NOT RETRY"
        return _out(False, state,
                    f"live gate: CLOSE ONLY did not prove a fill ({requested_action} {qty} "
                    f"{p.get('symbol', '')} {desc} -> {status}){retry}; all working "
                    f"orders were left unchanged [{errors}]", fill=fill)
    if order_type == "LMT" and status in ("Cancelled", "ApiCancelled", "Inactive"):
        errors = "; ".join(_ERRORS[-4:]) or "no IB error captured"
        return _out(False, "unknown" if float(trade.orderStatus.filled or 0) > 0 else "rejected",
                    f"live gate: CLOSE ONLY was rejected ({requested_action} {qty} "
                    f"{p.get('symbol', '')} {desc} -> {status}); all working orders were "
                    f"left unchanged [{errors}]", fill=fill)
    if status not in {"Submitted", "PreSubmitted", "Filled"}:
        return _out(False, "unknown", f"Close lacks broker acknowledgement ({status}); DO NOT RETRY", fill=fill)
    resting = " (RESTING, not yet filled)" if order_type == "LMT" and status != "Filled" else ""
    return _out(True, "executed",
                f"LIVE CLOSE ONLY {requested_action} {qty} {p.get('symbol', '')} {desc} "
                f"-> {status}{resting}; all working orders left unchanged", fill=fill)

def _confirm_leg_quantities(ib, expected, tries=4):
    """Poll until every permId shows its expected working quantity.

    Returns the legs that did NOT settle as (permId, wanted, seen) with `seen`
    None when the leg is gone or terminal. Empty list == the resize landed.
    """
    unsettled = []
    for _ in range(tries):
        ib.sleep(1.5)
        ib.reqAllOpenOrders()
        ib.sleep(0.4)
        live = {int(getattr(t.order, "permId", 0) or 0): t for t in ib.openTrades()}
        unsettled = []
        for perm, want in expected.items():
            t = live.get(int(perm))
            if t is None or str(getattr(t.orderStatus, "status", "")) in TERMINAL:
                unsettled.append((perm, int(want), None))
                continue
            try:
                saw = int(float(t.order.totalQuantity or 0))
            except (TypeError, ValueError):
                saw = None
            if saw != int(want):
                unsettled.append((perm, int(want), saw))
        if not unsettled:
            return []
    return unsettled

def _do_close_resize(ib, p, acct, host, port, main_cid):
    import position_actions
    return position_actions.run(globals(), ib, p, acct, host, port, main_cid, adding=False)

def _do_flatten(ib, p, host, port, main_cid):
    """Cancel this contract's working orders, then close.

    CANCEL-FIRST, and that ordering is the known cost: between the confirmed
    cancel and the close's fill the position carries no protection, and a
    partial close whose exit re-attach fails leaves the remainder naked.  Both
    outcomes are reported loudly rather than silently tolerated.  Disabled from
    2026-08 until 2026-09-03, when McKinley re-enabled it deliberately for the
    cases the safer paths cannot express -- a FULL close of a protected
    position, where cancelling the exits is unavoidable.  For a PARTIAL close
    prefer close_resize, which never cancels and never exposes the remainder.
    """
    sym = str(p.get("symbol", "")).upper()
    sec_type = str(p.get("sec_type") or "").upper()
    expiry = str(p.get("expiry") or "").strip()
    # Match on symbol AND sec_type AND expiry (the site sends all three). If the
    # payload can't pin ONE position, ABORT -- picking the first would close the
    # wrong contract month during a futures roll (and cancel both months' stops).
    ib.reqPositions()
    pos, err = _exact_position(ib, p)
    if err:
        return _out(False, "rejected", err)
    from execution_contracts import qualify_position
    try:
        pos = qualify_position(ib, pos)
    except (ValueError, BrokerMutationBlocked) as exc:
        return _out(False, "rejected", str(exc))
    ref = pos.contract
    # Option positions are combo books -- a symbol-scoped cancel+MKT close would
    # tear one leg out of a spread. Close them via a closing combo ticket (later
    # phase) or in TWS.
    if str(getattr(ref, "secType", "")).upper() == "OPT":
        return _out(False, "rejected",
                    "live gate: option positions can't be flattened here -- close via a "
                    "closing combo ticket (later phase) or TWS")
    # Close order style: MKT (default, RTH only) or LMT (works outside RTH).
    # outside_rth REQUIRES LMT — IBKR does not execute MKT closes outside RTH,
    # and the old always-MKT path reported exactly that failure mode.
    order_type = str(p.get("order_type") or "MKT").upper()
    if order_type not in ("MKT", "LMT"):
        return _out(False, "rejected", f"live gate: unsupported close order_type {order_type}")
    outside_rth = bool(p.get("outside_rth"))
    if outside_rth and order_type != "LMT":
        return _out(False, "rejected",
                    "live gate: outside-RTH close must be a LMT (IBKR ignores MKT outside RTH)")
    limit = p.get("limit")
    if order_type == "LMT":
        try:
            limit = float(limit)
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: LMT close needs a limit price")
        if not (0 < limit < 1e9):
            return _out(False, "rejected", "live gate: LMT close needs a positive limit price")
    tif = str(p.get("tif") or "DAY").upper()
    if tif not in ("DAY", "GTC"):
        return _out(False, "rejected", f"live gate: unsupported tif {tif}")
    if order_type == "MKT":
        tif = "DAY"                      # a GTC market order is a contradiction

    held0 = int(round(abs(pos.position)))
    qty_req = p.get("qty")
    if qty_req not in (None, ""):
        # Absolute share count. Rejected (not clamped) when above the held size:
        # an explicit number that doesn't match the live book means the user is
        # looking at stale state — fail safe instead of guessing.
        try:
            qty_req = float(qty_req)
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: qty must be a number")
        if qty_req <= 0 or qty_req != int(qty_req):
            return _out(False, "rejected", "live gate: qty must be a whole number > 0")
        qty_req = int(qty_req)
        if qty_req > held0:
            return _out(False, "rejected",
                        f"live gate: qty {qty_req} exceeds held {held0} {sym}")
        frac = None
        partial = qty_req < held0
    else:
        qty_req = None
        try:
            frac = float(p.get("fraction", 1.0) or 1.0)
        except (TypeError, ValueError):
            return _out(False, "rejected", "live gate: fraction must be a number")
        if not (0.0 < frac <= 1.0):      # clamp: never scale a flatten above the held size
            return _out(False, "rejected", f"live gate: fraction {frac:g} outside (0, 1]")
        partial = frac < 1.0
    close_action = "SELL" if pos.position > 0 else "BUY"
    # 1) cancel this CONTRACT's working orders FIRST (each via its placing client),
    #    confirm they're gone -- else ABORT so a bracket leg is never left naked.
    targets = _orders_for_contract(ib, ref, p.get("_broker_account"))
    legs = []
    if partial:
        # Trim: capture the exit legs BEFORE cancelling anything so they can be
        # re-placed on the remainder; abort (nothing cancelled) if any leg is
        # unreadable. Only close-direction legs are cancelled -- a pending
        # same-direction entry order stays working.
        legs, cap_err = _capture_exit_legs(targets, close_action)
        if legs is None:
            return _out(False, "rejected",
                        f"live gate: trim ABORTED ({cap_err}); nothing cancelled -- manage in TWS")
        if legs:
            cap_err = _validate_exit_topology(
                legs, held0, require_protective_exit=False)
            if cap_err:
                return _out(False, "rejected",
                            f"live gate: trim ABORTED ({cap_err}); nothing cancelled -- manage in TWS")
        targets = [t for t in targets if str(t.order.action).upper() == close_action]
    if targets:
        _, err = _cancel_via_owners(ib, host, port, main_cid, targets)
        if err:
            return _out(False, "unknown", f"live gate: {err}; cancellation needs reconciliation; DO NOT RETRY")
        remaining = _confirm_cancelled(ib, targets)
        if remaining:
            errs = "; ".join(_ERRORS[-4:]) or "no IB error captured"
            return _out(False, "unknown",
                        f"live gate: could not cancel {len(remaining)} working order(s) for {sym}; "
                        f"close ABORTED -- manage in TWS [{errs}]")
    # A stop/target may have FILLED (not cancelled) during the flatten, leaving us
    # already flat -- closing off the STALE position would OPEN a new opposite
    # position. Re-read the live position and size off THAT.
    ib.reqPositions()
    pos = next((x for x in ib.positions()
                if x.position and str(x.account) == p["_broker_account"]
                    and int(x.contract.conId) == int(p["con_id"])), None)
    if pos is None:
        return _out(True, "executed",
                    f"LIVE cancelled {len(targets)} order(s); {sym} already flat "
                    f"(a bracket leg filled during the flatten) -- no close placed",
                    fill={"cancelled": len(targets), "status": "AlreadyFlat"})

    # 2) close the position (or the trimmed part of it). Sized off the RE-READ
    # live position: with an absolute qty, clamp down if a leg filled during the
    # cancel step (never open an opposite position).
    live_held = int(abs(pos.position))
    if partial and (pos.position > 0) != (close_action == "SELL"):
        return _out(False, "unknown", "Position direction changed during cancellation; reconcile before retry")
    n = min(qty_req, live_held) if qty_req is not None else \
        min(int(round(abs(pos.position) * frac)), live_held)
    if not partial:
        n = live_held  # full Flatten includes fills racing entry cancellation
    if n <= 0:
        return _out(False, "rejected", "live gate: zero qty")
    c = ref  # qualified exact-account contract from before cancellation
    action = "SELL" if pos.position > 0 else "BUY"
    if order_type == "LMT":
        o = LimitOrder(action, n, limit)
        if outside_rth:
            o.outsideRth = True         # pre/post-market eligible (LMT only)
    else:
        o = MarketOrder(action, n)
    o.tif = tif                         # explicit -- the PA Gateway coerces unset tif (Err 10349)
    # Route the close to the account that actually HOLDS the position -- NOT
    # managedAccounts()[0]. On a multi-account / FA login those differ, so the
    # order misroutes to an account without the position and IBKR CANCELS it.
    # (First suspected as the 2026-07-01 GLNG non-close; the real killer there
    # was the direct-route discard fixed above. Keeping the account pin -- it's
    # correct on its own terms.)
    if getattr(pos, "account", None):
        o.account = pos.account
    _ERRORS.clear()                     # isolate THIS order's errors from the cancel step
    t = guarded_place_order(
        ib,
        c,
        o,
        mutation_kind="exit",
        signal_id=_command_signal(p, "flatten:close"),
        account=p["_broker_account"],
    )
    # Poll for the fill instead of a blind 2s "executed". A MARKET close that does
    # NOT fill (outside RTH, precaution hold, reject) must be reported as a FAILURE
    # so a position is never silently left open (this masked a real miss 2026-07-01).
    # A LIMIT close is a RESTING order: a short ack wait, then working == success.
    for _ in range(12 if order_type == "MKT" else 4):
        ib.sleep(1.0)
        if t.orderStatus.status in ("Filled", "Cancelled", "ApiCancelled", "Inactive"):
            break
    st = t.orderStatus.status
    desc = f"{order_type}{f' @ {limit:g}' if order_type == 'LMT' else ''}" \
           f"{' outsideRTH' if outside_rth else ''} ({tif})"
    fill = {"order_id": t.order.orderId, "status": st, "cancelled": len(targets),
            "filled": t.orderStatus.filled, "avg_fill": t.orderStatus.avgFillPrice}
    # Trim: re-attach the captured exit legs, whether or not the close filled --
    # the remainder must never be left without its exits. Sizing: live position
    # minus whatever the close order is STILL WORKING for. A filled MKT close
    # reduces the live position itself (still-working 0); a resting LMT hasn't,
    # so exits cover the eventual remainder and exits + working close together
    # equal exactly the held quantity (no overfill). A dead close (Cancelled /
    # Inactive) has still-working 0, so exits restore at the full held size.
    reattach_note, reattach_failed, remaining_qty = "", False, 0
    if partial and legs:
        ib.sleep(1.0)                   # let the post-fill position update land
        ib.reqPositions()
        rem = next((x for x in ib.positions()
                    if x.position and str(x.account) == p["_broker_account"]
                    and int(x.contract.conId) == int(p["con_id"])), None)
        if rem is not None and (rem.position > 0) != (close_action == "SELL"):
            return _out(False, "unknown", "Position direction changed before exit restoration; DO NOT RETRY", fill=fill)
        live_qty = int(round(abs(rem.position))) if rem is not None else 0
        live_qty = min(live_qty, max(0, live_held - int(t.orderStatus.filled or 0)))
        still_working = 0 if st in TERMINAL else max(0, n - int(t.orderStatus.filled or 0))
        remaining_qty = max(0, live_qty - still_working)
        fill["remaining"] = remaining_qty
        if remaining_qty > 0:
            try:
                placed = _replace_exit_legs(ib, c, legs, close_action, remaining_qty,
                                            getattr(pos, "account", None),
                                            _command_signal(p, "flatten:reattach-exits"))
                fill["reattach_orders"] = _placed_ids(placed)
                problem = _placement_problem(placed, ib=ib)
                if problem or len(placed) != len(legs):
                    raise ValueError(problem or "exit restoration count mismatch")
                fill["reattached"] = len(placed)
                reattach_note = f"; re-attached {len(placed)} exit leg(s) @ qty {remaining_qty}"
            except Exception as e:  # noqa: BLE001
                reattach_failed = True
                fill["reattached"] = 0
                reattach_note = (f"; exit re-attach FAILED ({type(e).__name__}) -- "
                                 f"REMAINDER ~{remaining_qty} HAS UNVERIFIED EXIT COVERAGE, manage in TWS")
    if order_type == "MKT" and st != "Filled":
        errs = "; ".join(_ERRORS[-4:]) or "no IB error captured"
        return _out(False, "unknown" if st not in TERMINAL or float(t.orderStatus.filled or 0) > 0 else "rejected",
                    f"DO NOT RETRY before reconciliation: cancelled {len(targets)} order(s) but CLOSE did NOT fill "
                    f"({action} {n} {sym} {desc} -> {st}); confirmed filled {t.orderStatus.filled:g}/{n}"
                    f"{reattach_note} -- manage in TWS [{errs}]", fill=fill)
    if order_type == "LMT" and st in ("Cancelled", "ApiCancelled", "Inactive"):
        errs = "; ".join(_ERRORS[-4:]) or "no IB error captured"
        return _out(False, "unknown" if float(t.orderStatus.filled or 0) > 0 or reattach_failed else "rejected",
                    f"live gate: cancelled {len(targets)} order(s) but the LMT close ended "
                    f"({action} {n} {sym} {desc} -> {st}); "
                    f"confirmed filled {t.orderStatus.filled:g}/{n}{reattach_note} -- manage in TWS [{errs}]", fill=fill)
    if reattach_failed:
        return _out(False, "unknown",
                    f"live gate: trim {action} {n} {sym} {desc} -> {st} "
                    f"but exit re-attach FAILED -- REMAINDER ~{remaining_qty} HAS UNVERIFIED EXIT COVERAGE; "
                    f"manage in TWS", fill=fill)
    if st not in {"Submitted", "PreSubmitted", "Filled"}:
        return _out(False, "unknown", f"Flatten close lacks broker acknowledgement ({st}); DO NOT RETRY", fill=fill)
    naked_note = ""
    if order_type == "LMT" and st != "Filled" and not partial:
        naked_note = (" -- NOTE: all exits were cancelled; the position rests "
                      "UNPROTECTED behind this working close until it fills")
    if order_type == "LMT" and st != "Filled":
        return _out(True, "executed",
                    f"LIVE cancelled {len(targets)} order(s) + {action} {n} {sym} {desc} "
                    f"-> {st} (RESTING, not yet filled){reattach_note}{naked_note}", fill=fill)
    return _out(True, "executed",
                f"LIVE cancelled {len(targets)} order(s) + {action} {n} {sym} {desc} -> {st} "
                f"@ {t.orderStatus.avgFillPrice}{reattach_note}", fill=fill)

def _do_cancel(ib, p, host, port, main_cid):
    import order_mutations
    return order_mutations.run(globals(), ib, p, host, port, main_cid, modify=False, account_key=None)

def _do_modify(ib, p, host, port, main_cid, acct):
    import order_mutations
    return order_mutations.run(globals(), ib, p, host, port, main_cid, modify=True, account_key=acct)

def main():
    try:
        cmd = json.loads(sys.argv[1])
    except Exception:
        return _out(False, "error", "bad command json")
    t = cmd.get("type")
    p = dict(cmd.get("payload") or {})
    p["_command_id"] = str(cmd.get("id") or "").strip()
    acct = cmd.get("account")

    if not LIVE_ENABLED:
        return _out(False, "rejected", "live gate: AGENT_LIVE_ENABLED not set")
    if not p["_command_id"]:
        return _out(False, "rejected", "live gate: durable command id is required")
    if acct not in LIVE_ACCOUNTS:
        return _out(False, "rejected", f"live gate: account {acct} not armed")
    if t not in LIVE_TYPES:
        return _out(False, "rejected", f"live gate: type {t} not armed")
    if t in DISABLED_UNSAFE_MUTATIONS - {"add_to_position", "cancel", "modify"}:
        return _out(
            False,
            "rejected",
            f"live gate: {t} is disabled until it has an atomic, exact-identity "
            "broker lifecycle; to reduce a position use close_only (bare), "
            "close_resize (partial, shrinks the exits first) or flatten",
        )
    if t not in SUPPORTED:
        return _out(False, "rejected", f"live gate: {t} not supported live")

    host, port, cid = PORTS[acct]
    ib = IB()
    try:
        ib.connect(host, port, clientId=cid, timeout=8)        # NOT readonly
    except Exception as e:  # noqa: BLE001
        return _out(False, "rejected", f"live gate: connect failed ({type(e).__name__})")
    ib.errorEvent += _on_err
    try:
        try:
            p["_broker_account"] = _resolve_broker_account(ib, acct)
        except Exception as exc:
            return _out(False, "rejected", f"live gate: broker account resolution failed ({exc})")
        if t == "entry_bracket":
            return _do_entry_bracket(ib, p, acct)
        if t == "exit_attach":
            return _do_exit_attach(ib, p, acct)
        if t == "close_only":
            return _do_close_only(ib, p)
        if t == "close_resize":
            return _do_close_resize(ib, p, acct, host, port, cid)
        if t == "flatten":
            return _do_flatten(ib, p, host, port, cid)
        if t == "trim_readd":
            return _do_trim_readd(ib, p, acct, host, port, cid)
        if t == "add_to_position":
            return _do_add_to_position(ib, p, acct, host, port, cid)
        if t == "cancel":
            return _do_cancel(ib, p, host, port, cid)
        if t == "modify":
            return _do_modify(ib, p, host, port, cid, acct)
        if t == "option_spread":
            return _do_option_spread(ib, p, acct)
        return _out(False, "rejected", f"live gate: {t} unhandled")
    except Exception as e:  # noqa: BLE001
        return _out(
            False,
            "unknown",
            f"execute became indeterminate ({type(e).__name__}); "
            "VERIFY IN TWS AND DO NOT RETRY",
        )
    finally:
        try:
            ib.disconnect()
        except Exception:  # noqa: BLE001
            pass
